/* Standalone bus route workspace. All visual changes stay inside its own shell. */
body.dxbus-page {
	--dxbus-canvas: #080b0d;
	--dxbus-surface: #101416;
	--dxbus-surface-raised: #171c1f;
	--dxbus-line: #2d3438;
	--dxbus-ink: #f4f5f3;
	--dxbus-muted: #a5afb4;
	--dxbus-gold: #e1b75f;
	--dxbus-route: #ed343d;
	--dxbus-route-ink: #fff;
	--dxbus-sidebar-width: 232px;
	margin: 0;
	padding: 0;
	background: var(--dxbus-canvas);
	color: var(--dxbus-ink);
	color-scheme: dark;
	font:
		400 14px/1.55 "Outfit",
		sans-serif;
	overflow-x: clip;

	#wrapper,
	#main {
		margin: 0;
		padding: 0;
		width: 100%;
		max-width: none;
		min-height: 100dvh;
		overflow: visible;
	}

	&.dxbus-menu-open {
		overflow: hidden;

		@include media-breakpoint-up(lg) {
			overflow: visible;
		}
	}

	@include media-breakpoint-up(xxl) {
		--dxbus-sidebar-width: 252px;
	}
}

.dxbus-app {
	--gold: var(--dxbus-gold);
	--line: var(--dxbus-line);
	--muted: var(--dxbus-muted);
	min-height: 100dvh;
	background: var(--dxbus-canvas);
	color: var(--dxbus-ink);
	isolation: isolate;

	&[data-service-type="night"],
	&[data-route-theme="night"] {
		--dxbus-route: #c1e7fb;
		--dxbus-route-ink: #071119;
	}

	*,
	*::before,
	*::after {
		box-sizing: border-box;
	}

	[hidden] {
		display: none !important;
	}

	h1,
	h2,
	h3,
	h4,
	p,
	figure {
		margin: 0;
		padding: 0;
	}

	h1,
	h2,
	h3,
	h4 {
		font-family: "Outfit", sans-serif;
		text-transform: none;
		letter-spacing: -0.025em;
		line-height: 1.25;
		font-weight: 500;
		color: var(--dxbus-ink);
	}

	h1 {
		font-size: clamp(24px, 3vw, 36px);
	}

	h2 {
		font-size: 20px;
	}

	h3 {
		font-size: 16px;
	}

	a {
		color: inherit;
		text-decoration: none;
	}

	button,
	input,
	select,
	textarea {
		font: inherit;
		letter-spacing: 0;
		text-transform: none;
		-webkit-tap-highlight-color: transparent;
	}

	button,
	summary {
		cursor: pointer;
	}

	button,
	a,
	summary,
	input,
	select,
	textarea {
		touch-action: manipulation;
	}

	button:disabled {
		cursor: wait;
		opacity: 0.55;
	}

	:focus-visible {
		outline: 2px solid var(--dxbus-gold);
		outline-offset: 4px;
	}

	svg:not(.leaflet-zoom-animated) {
		width: 20px;
		height: 20px;
		flex: 0 0 auto;
	}

	img {
		max-width: 100%;
	}

	.dxbus-skip,
	> .screen-reader-text {
		position: fixed;
		left: 18px;
		top: -100px;
		z-index: 1001;
		padding: 12px 18px;
		background: var(--dxbus-gold);
		color: #0b0f11;

		&:focus {
			top: 14px;
		}
	}

	.dxbus-sidebar {
		position: fixed;
		inset: 0 auto 0 0;
		z-index: 100;
		display: flex;
		flex-direction: column;
		width: min(300px, calc(100vw - 32px));
		height: 100dvh;
		padding: 27px 18px 18px;
		border-right: 1px solid #ffffff0c;
		background: #0c1012;
		overflow-y: auto;
		overscroll-behavior: contain;
		transform: translateX(-102%);
		visibility: hidden;
		transition:
			transform 0.32s cubic-bezier(0.22, 1, 0.36, 1),
			visibility 0.32s;

		nav {
			display: grid;
			gap: 4px;
		}

		@include media-breakpoint-up(lg) {
			width: var(--dxbus-sidebar-width);
			visibility: visible;
			transform: none;
			padding: 31px 18px 22px;
		}
	}

	.dxbus-brand {
		display: inline-flex;
		flex-direction: column;
		align-items: flex-start;
		gap: 5px;
		margin: 0 10px 32px;
		color: var(--dxbus-ink);
		font-size: 15px;
		letter-spacing: 0.4em;
		line-height: 1.35;
		font-weight: 400;

		small,
		span:last-child:not(:first-child) {
			font-size: 11px;
			letter-spacing: 0.15em;
			color: var(--dxbus-muted);
		}
	}

	.dxbus-sidebar__search {
		position: relative;
		display: flex;
		align-items: center;
		gap: 8px;
		margin-bottom: 28px;
		border: 1px solid transparent;
		border-radius: 6px;
		background: var(--dxbus-surface-raised);
		color: var(--dxbus-muted);

		input {
			min-width: 0;
			width: 100%;
			padding: 11px 12px;
			border: 0;
			border-radius: inherit;
			background: transparent;
			color: var(--dxbus-ink);
			font-size: 12px;
		}

		button {
			width: 100%;
			padding: 11px 12px;
			display: flex;
			align-items: center;
			gap: 9px;
			border: 0;
			background: transparent;
			color: inherit;
			font-size: 12px;
			text-align: left;
		}

		&:focus-within {
			border-color: var(--dxbus-gold);
		}

		svg {
			width: 16px;
			height: 16px;
		}
	}

	.dxbus-sidebar__label,
	.dxbus-nav-label {
		margin: 21px 11px 10px;
		color: var(--dxbus-muted);
		font-size: 10px;
		letter-spacing: 0.16em;
		text-transform: uppercase;
	}

	.dxbus-sidebar__routes,
	.dxbus-recent-routes,
	.dxbus-recent {
		display: grid;
		gap: 5px;
	}

	.dxbus-nav-link,
	.dxbus-sidebar__routes > a,
	.dxbus-recent-routes > a,
	.dxbus-recent > a,
	.dxbus-recent > button,
	.dxbus-sidebar__all {
		position: relative;
		display: flex;
		align-items: center;
		gap: 12px;
		min-height: 43px;
		padding: 10px 12px;
		border: 1px solid transparent;
		border-radius: 6px;
		color: #bfc6ca;
		font-size: 13px;
		line-height: 1.4;
		transition:
			color 0.22s ease,
			background-color 0.22s ease,
			border-color 0.22s ease;

		svg {
			width: 18px;
			height: 18px;
		}

		&:is(:hover, :focus-visible) {
			background: #ffffff07;
			color: #fff;
			border-color: #ffffff0a;
		}

		&[aria-current],
		&[aria-selected="true"],
		&.is-active {
			background: #e1b75f10;
			color: #fff;
			border-color: #e1b75f0d;

			&::before {
				content: "";
				position: absolute;
				left: -1px;
				top: 10px;
				bottom: 10px;
				width: 2px;
				border-radius: 1px;
				background: var(--dxbus-gold);
			}

			svg {
				color: var(--dxbus-gold);
			}
		}

		> small,
		.dxbus-pin-count {
			margin-left: auto;
			padding: 1px 5px;
			font-size: 11px;
			color: var(--dxbus-muted);
			border: 1px solid var(--dxbus-line);
			border-radius: 3px;
		}
	}

	.dxbus-sidebar__routes > a[aria-current],
	.dxbus-recent-routes > a[aria-current],
	.dxbus-recent > a[aria-current] {
		background: var(--dxbus-route);
		color: var(--dxbus-route-ink);
		border-color: transparent;

		&::before {
			display: none;
		}
	}

	.dxbus-sidebar__bottom {
		margin-top: auto;
		padding-top: 28px;

		a {
			display: flex;
			align-items: center;
			gap: 8px;
			padding: 10px;
			font-size: 12px;
			color: var(--dxbus-muted);
			transition: color 0.2s ease;

			&:hover {
				color: var(--dxbus-gold);
			}
		}
	}

	.dxbus-sidebar-scrim {
		position: fixed;
		inset: 0;
		z-index: 99;
		border: 0;
		background: #020507b3;
		backdrop-filter: blur(4px);
		opacity: 0;
		visibility: hidden;
		transition:
			opacity 0.32s ease,
			visibility 0.32s;

		@include media-breakpoint-up(lg) {
			display: none;
		}
	}

	&.is-menu-open,
	&.is-sidebar-open {
		.dxbus-sidebar {
			transform: none;
			visibility: visible;
		}

		.dxbus-sidebar-scrim {
			opacity: 1;
			visibility: visible;
		}
	}

	.dxbus-topbar__start,
	.dxbus-topbar__actions {
		display: flex;
		align-items: center;
		gap: 9px;
	}

	#dxb-share {
		display: none;

		@include media-breakpoint-up(md) {
			display: inline-flex;
		}
	}

	.dxbus-eyebrow {
		font-size: 10px;
		letter-spacing: 0.13em;
		text-transform: uppercase;
		color: var(--dxbus-gold);
	}

	.dxbus-link {
		display: inline-block;
		margin-top: 12px;
		color: var(--dxbus-gold);
		font-size: 12px;
	}

	.dxbus-sidebar__bottom > small {
		display: block;
		padding: 9px 10px 0;
		font-size: 10px;
		color: #7f8e96;
	}

	.dxbus-sidebar__search {
		> svg {
			margin-left: 12px;
			flex-shrink: 0;
		}

		input#dxb-route-input {
			padding: 10px 10px 10px 0;
			font:
				400 12px/1.5 "Outfit",
				sans-serif;
			min-height: 39px;
			border: 0;
			background: transparent;
			text-transform: none;
		}

		.dxbus-lookup__options {
			position: absolute;
			z-index: 3;
			top: calc(100% + 7px);
			left: 0;
			width: 100%;
			max-height: 360px;
			overflow: auto;
			list-style: none;
			margin: 0;
			padding: 5px;
			border: 1px solid #5c6566;
			border-radius: 5px;
			background: #192226;

			li + li {
				border-top: 1px solid #ffffff0c;
			}

			[aria-selected="true"] {
				background: #e1b75f20;
			}

			button {
				font-size: 11px;
				padding: 9px 7px;
			}

			strong {
				color: var(--dxbus-route);
				font:
					400 18px/1 "Railway",
					"Outfit",
					sans-serif;
			}
		}
	}

	.dxbus-status {
		position: fixed;
		z-index: 15;
		right: 18px;
		bottom: 18px;
		width: fit-content;
		max-width: min(420px, calc(100vw - 36px));
		padding: 8px 13px;
		border: 1px solid #56615c;
		border-radius: 5px;
		background: #152022f2;
		color: #c6d3d6;
		font-size: 11px;
		box-shadow: 0 6px 24px #0005;

		&:empty {
			display: none;
		}

		&.is-error {
			border-color: #b88c56;
			color: #edd2b4;
		}
	}

	.dxbus-explorer-toolbar {
		display: flex;
		align-items: flex-end;
		justify-content: space-between;
		flex-wrap: wrap;
		gap: 18px;
		padding-block: 18px;

		label {
			flex: 1 1 230px;
			font-size: 12px;
			color: var(--dxbus-muted);
		}

		.dxbus-segment {
			margin: 0;
		}
	}

	.dxbus-card--map {
		.dxbus-segment {
			margin: 12px 0 8px;
		}

		#dxbus-overview-direction {
			min-height: 35px;
			margin: 0 0 9px;
			padding-block: 6px;
			font-size: 11px;
		}
	}

	.dxbus-attribution {
		padding-top: 20px;
		margin-top: 25px;
		border-top: 1px solid var(--dxbus-line);
		color: #81939d;
		font-size: 10px;
		line-height: 1.7;

		a {
			color: #bcc8cc;
		}
	}

	#dxb-gallery {
		margin-top: 20px;
	}

	.dxbus-main {
		position: relative;
		width: 100%;
		min-width: 0;
		max-width: 1700px;
		margin: 0 auto;
		padding: 0 17px 30px;

		@include media-breakpoint-up(md) {
			padding: 0 28px 35px;
		}

		@include media-breakpoint-up(lg) {
			width: calc(100% - var(--dxbus-sidebar-width));
			margin-left: var(--dxbus-sidebar-width);
			padding: 0 30px 38px;
		}

		@include media-breakpoint-up(xxl) {
			padding-inline: 38px;
		}
	}

	.dxbus-topbar {
		position: relative;
		z-index: 3;
		display: flex;
		align-items: center;
		gap: 13px;
		min-height: 65px;
		padding-block: 13px;
		font-size: 12px;

		> :last-child {
			margin-left: auto;
		}

		nav,
		.dxbus-breadcrumb {
			display: flex;
			align-items: center;
			gap: 10px;
			color: #c7ced2;
		}

		a:hover {
			color: var(--dxbus-gold);
		}

		button,
		.dxbus-switch {
			min-height: 38px;
			padding: 7px 13px;
			border: 1px solid #ceb77970;
			border-radius: 24px;
			background: #0d1219a6;
			color: #fff;
			font-size: 12px;
			backdrop-filter: blur(8px);
			transition:
				border-color 0.22s ease,
				background-color 0.22s ease;

			&:is(:hover, :focus-visible) {
				background: #252725;
				border-color: var(--dxbus-gold);
			}
		}

		[data-dxbus-menu] {
			width: 38px;
			padding: 8px;
			border-color: var(--dxbus-line);
			border-radius: 5px;

			@include media-breakpoint-up(lg) {
				display: none;
			}
		}
	}

	.dxbus-hero {
		position: relative;
		isolation: isolate;
		min-height: 292px;
		margin: -65px -17px 0;
		padding: 91px 17px 34px;
		overflow: hidden;
		background: #11181b;

		&::after {
			content: "";
			position: absolute;
			inset: 0;
			z-index: -1;
			background: linear-gradient(
					0deg,
					var(--dxbus-canvas) 0% 6%,
					transparent 70%
				),
				linear-gradient(90deg, #080b0de6, #080b0d70 72%, #080b0d22);
			pointer-events: none;
		}

		@include media-breakpoint-up(md) {
			margin-inline: -28px;
			padding-inline: 28px;
			display: flex;
			flex-direction: column;
			justify-content: flex-end;
			min-height: 500px;
			padding-top: 100px;
		}

		@include media-breakpoint-up(lg) {
			margin-inline: -30px;
			padding-inline: 30px;
		}

		@include media-breakpoint-up(xxl) {
			margin-inline: -38px;
			padding-inline: 38px;
		}
	}

	.dxbus-hero__image {
		position: absolute;
		inset: 0;
		z-index: -2;
		width: 100%;
		height: 100%;
		object-fit: cover;
		object-position: 64% 44%;
		opacity: 0.72;
		transition: opacity 0.5s ease;

		> img {
			width: 100%;
			height: 100%;
			object-fit: cover;
			object-position: inherit;
		}

		@include media-breakpoint-up(md) {
			object-position: 68% 47%;
			opacity: 0.9;
		}
	}

	.dxbus-hero__content {
		position: relative;
		display: block;
		max-width: 850px;

		h1 {
			font-size: clamp(24px, 2.25vw, 36px);
			text-wrap: balance;
			max-width: 700px;
		}

		p {
			margin-top: 8px;
			font-size: 14px;
			color: #e4e7e7;
		}

		.dxbus-eyebrow,
		.dxb-eyebrow {
			margin: 0 0 7px;
			color: #e1e5e7;
			font-size: 10px;
			text-transform: uppercase;
			letter-spacing: 0.12em;
		}
	}

	.dxbus-route-identity {
		display: flex;
		align-items: center;
		gap: 17px;

		> div {
			min-width: 0;
		}

		@include media-breakpoint-up(md) {
			gap: 25px;
		}
	}

	.dxbus-route-badge,
	#dxb-route-number.dxbus-route-badge {
		display: flex;
		align-items: center;
		justify-content: center;
		min-width: 91px;
		min-height: 90px;
		padding: 5px 13px;
		background: var(--dxbus-route);
		color: var(--dxbus-route-ink);
		font:
			400 clamp(49px, 5.3vw, 80px) / 1 "Railway",
			"Outfit",
			sans-serif;
		letter-spacing: -0.05em;
		text-shadow: none;
		-webkit-text-fill-color: currentColor;
		flex-shrink: 0;
		border-radius: 1px;

		@include media-breakpoint-up(md) {
			min-width: 120px;
			min-height: 111px;
			padding-inline: 18px;
		}
	}

	.dxbus-meta {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		gap: 8px;
		margin-top: 23px;

		> span,
		> a,
		.dxbus-route-chip {
			display: inline-flex;
			align-items: center;
			gap: 8px;
			max-width: 100%;
			padding: 6px 12px;
			min-height: 33px;
			border: 1px solid #b9a06061;
			border-radius: 20px;
			background: #070a0bb3;
			color: #f1f0ea;
			font-size: 12px;
			line-height: 1.5;
			text-transform: uppercase;
			letter-spacing: 0.035em;
		}

		> :first-child {
			color: var(--dxbus-gold);
		}

		svg {
			width: 16px;
			height: 16px;
		}
	}

	.dxbus-stats {
		position: relative;
		z-index: 1;
		display: grid;
		grid-template-columns: repeat(2, minmax(0, 1fr));
		gap: 10px;
		margin-top: -5px;
		margin-bottom: 20px;

		@include media-breakpoint-up(md) {
			grid-template-columns: repeat(4, minmax(0, 1fr));
			gap: 14px;
			margin-top: -15px;
		}
	}

	.dxbus-stat {
		display: grid;
		grid-template-columns: auto 1fr;
		align-content: center;
		column-gap: 13px;
		row-gap: 1px;
		min-width: 0;
		min-height: 104px;
		padding: 15px 13px;
		border: 1px solid var(--dxbus-line);
		border-radius: 8px;
		background: #101416f5;

		> svg,
		> .dxbus-stat__icon {
			grid-row: 1 / 4;
			align-self: center;
			color: var(--dxbus-route);
			width: 27px;
			height: 27px;
		}

		strong,
		[data-dxbus-value],
		.dxbus-stat__value {
			font-size: 29px;
			line-height: 1.1;
			font-weight: 500;
			color: var(--dxbus-ink);
		}

		> span:not(.dxbus-stat__icon),
		> div > span,
		.dxbus-stat__label {
			font-size: 9px;
			text-transform: uppercase;
			letter-spacing: 0.09em;
			line-height: 1.6;
			color: #d8dddf;
		}

		small,
		.dxbus-stat__note {
			font-size: 10px;
			line-height: 1.5;
			color: var(--dxbus-muted);
		}

		> div {
			display: flex;
			flex-direction: column;
			min-width: 0;
		}

		&:first-child strong,
		&.dxbus-stat--refresh strong {
			color: var(--dxbus-gold);
		}

		@include media-breakpoint-up(xl) {
			padding: 18px 20px;
			column-gap: 17px;
		}
	}

	.dxbus-overview-grid {
		display: grid;
		grid-template-columns: minmax(0, 1fr);
		gap: 15px;

		@include media-breakpoint-up(md) {
			grid-template-columns: repeat(6, minmax(0, 1fr));

			> .dxbus-card {
				grid-column: span 3;
			}

			> .dxbus-card--map,
			> .dxbus-card--description {
				grid-column: 1 / -1;
			}
		}

		@include media-breakpoint-up(xl) {
			grid-template-columns: repeat(12, minmax(0, 1fr));
			gap: 18px;

			> .dxbus-card {
				grid-column: span 4;
			}

			> .dxbus-card--description {
				grid-column: span 8;
			}
		}
	}

	.dxbus-card {
		min-width: 0;
		border: 1px solid var(--dxbus-line);
		border-radius: 8px;
		background: var(--dxbus-surface);
		overflow: clip;
	}

	.dxbus-card__head {
		display: flex;
		justify-content: space-between;
		align-items: center;
		gap: 12px;
		padding: 17px 17px 14px;

		h2,
