/* Route photographs use the same photo-left/details-right arrangement as the main gallery. */
body.dxbus-page #dxb-lightbox {
	width: min(1480px, calc(100vw - 28px));
	max-height: calc(100dvh - 32px);
	padding: 0;
	border-radius: 0;
	overflow: auto;

	&[open] {
		display: block;
	}

	.dxb-photo-viewport {
		position: relative;
		display: grid;
		grid-template-columns: minmax(0, 1fr);
		grid-template-rows: minmax(0, 1fr);
		place-items: center;
		min-width: 0;
		height: 52dvh;
		background: #06090b;
		overflow: hidden;
		overscroll-behavior: contain;

		#dxb-lightbox-image {
			display: block;
			width: 100%;
			min-width: 0;
			max-width: 100%;
			min-height: 0;
			height: 100% !important;
			max-height: 100% !important;
			object-fit: contain;
			transform-origin: center;
			transition: transform 0.45s cubic-bezier(0.22, 1, 0.36, 1);
		}
	}

	&.is-zoomed .dxb-photo-viewport {
		touch-action: none;
		cursor: grab;
		&:active {
			cursor: grabbing;
		}
	}

	.dxb-lightbox-info {
		position: relative;
		display: flex;
		flex-direction: column;
		min-width: 0;
		height: auto;
		padding: 24px 20px 16px;
		background: #10171b;
		overflow: visible;
