	.dxb-lightbox-details {
		min-width: 0;
		min-height: 0;
		overflow: visible;
		overflow-wrap: anywhere;
	}

	#dxb-lightbox-route {
		margin-bottom: 8px;
		color: #e1b75f;
		font-size: 11px;
		letter-spacing: 0.08em;
		text-transform: uppercase;
	}

	#dxb-lightbox-title {
		margin-bottom: 14px;
	}
	#dxb-lightbox-caption,
	#dxb-lightbox-meta {
		font-size: 13px;
		line-height: 1.65;
		&:not(:empty) {
			margin-bottom: 14px;
		}
	}
	#dxb-lightbox-meta {
		color: #a5afb4;
	}

	#dxb-photo-technical {
		grid-template-columns: minmax(0, 1fr) minmax(0, 1.2fr);
