		margin: 22px 0;
		dt {
			font-size: 10px;
			line-height: 1.65;
		}
		dd {
			text-align: right;
			font-size: 12px;
			line-height: 1.65;
		}
	}

	#dxb-photo-map {
		min-width: 0;
		max-width: 100%;
		iframe {
			display: block;
			width: 100%;
			height: 190px;
		}
	}

	.dxb-lightbox-nav {
		position: sticky;
		bottom: -16px;
		z-index: 2;
		display: grid;
		grid-template-columns: max-content minmax(0, 1fr) max-content;
		align-items: center;
		gap: 10px;
		flex-shrink: 0;
		min-height: 60px;
		margin-top: 22px;
		padding: 16px 0 0;
		background: #10171b;
		border-top: 1px solid #2d373d;

		button {
			min-height: 42px;
			padding: 8px 12px;
			white-space: nowrap;
			&:last-child {
				justify-self: end;
			}
		}
		#dxb-lightbox-count {
			text-align: center;
			white-space: nowrap;
		}
	}

	.dxb-close {
		z-index: 4;
	}

	@include media-breakpoint-up(lg) {
		&[open] {
			display: grid;
			grid-template-columns: minmax(0, 1fr) minmax(300px, 340px);
			align-items: stretch;
			height: min(880px, calc(100dvh - 48px));
			overflow: hidden;
		}

		.dxb-photo-viewport {
			height: 100%;
			min-height: 0;
		}
		.dxb-lightbox-info {
			min-height: 0;
			height: 100%;
			max-height: 100%;
			padding: 66px 24px 20px;
			border-left: 1px solid #2d373d;
			overflow: hidden;
		}

		.dxb-lightbox-details {
			flex: 1;
			padding-right: 8px;
			overflow-x: hidden;
			overflow-y: auto;
			overscroll-behavior: contain;
			scrollbar-width: thin;
		}

		.dxb-lightbox-nav {
			position: relative;
			bottom: auto;
			margin-top: 18px;
		}
	}
}

/* The legacy consultations margin must not offset the second dashboard column. */
