@keyframes dxbus-route-picture-arrive {
	from {
		opacity: 0;
		transform: scale(1.055);
		filter: grayscale(0);
	}
	to {
		opacity: 1;
		transform: scale(1);
		filter: grayscale(var(--dxbus-photo-muted, 0));
	}
}
@keyframes dxbus-route-halo {
	0%,
	100% {
		transform: translateY(0) rotate(-9deg);
		opacity: 0.8;
	}
	50% {
		transform: translateY(-4px) rotate(-5deg);
		opacity: 1;
	}
}
@keyframes dxbus-route-candle {
	from {
		transform: scale(0.9, 1) rotate(-4deg);
		opacity: 0.72;
	}
	to {
		transform: scale(1.1, 0.9) rotate(5deg);
		opacity: 1;
	}
}
@keyframes dxbus-feedback-arrive {
	from {
		opacity: 0;
		transform: translateY(-8px);
	}
	to {
		opacity: 1;
		transform: translateY(0);
	}
}
@keyframes dxbus-loading-pulse {
	0%,
	100% {
		opacity: 0.5;
		transform: translateY(0);
	}
	50% {
		opacity: 1;
		transform: translateY(-4px);
	}
}
@keyframes dxbus-loading-sweep {
	from {
		background-position: 100% 0;
	}
	to {
		background-position: -100% 0;
	}
}

@media (prefers-reduced-motion: reduce) {
	body.dxbus-page {
		.dxbus-hero,
		.dxbus-hero__image > img,
		.dxbus-stat,
		.dxbus-route-memorial::before,
		.dxbus-memorial-candles::before,
