/* CV*/
/* Editorial CV. All page styles are scoped to the CV template. */
body.is-frontend.page-cv,
body.is-frontend.page-template-page-cv {
	background: #090c0b;
	color: #f3f1eb;
}
body.is-frontend.page-cv #main,
body.is-frontend.page-template-page-cv #main {
	margin: 0;
	padding: 0;
	overflow: visible;
	min-height: 100vh;
}
.cv-experience {
	--cv-gold: #d9b974;
	--cv-text: #f3f1eb;
	--cv-muted: #b0b5ae;
	--cv-line: #303630;
	--cv-bg: #090c0b;
	font-family: "Outfit", sans-serif;
	color: var(--cv-text);
	overflow-wrap: break-word;
	*,
	*::before,
	*::after {
		box-sizing: border-box;
	}
	.cv-wrap {
		margin-inline: auto;
	}
	h1,
	h2,
	h3,
	h4 {
		font-family: "Outfit", sans-serif;
		color: var(--cv-text);
	}
	.cv-kicker {
		color: var(--cv-gold);
		text-transform: uppercase;
		letter-spacing: 0.21em;
		font:
			400 11px/1.7 "Outfit",
			sans-serif;
		margin: 0 0 25px;
		span {
			margin: 0 12px;
		}
	}
	a {
		color: inherit;
		text-decoration: none;
		&:focus-visible {
			outline: 2px solid var(--cv-gold);
			outline-offset: 6px;
		}
	}
	.cv-hero {
		position: relative;
		min-height: 100svh;
		isolation: isolate;
		background: #090c0b;
		&::after {
			content: "";
			position: absolute;
			inset: 0;
			z-index: -1;
			pointer-events: none;
		}
	}
	.cv-hero__portrait {
		position: absolute;
		z-index: -2;
		overflow: hidden;
		img {
			width: 100%;
			height: 100%;
			object-fit: cover;
			filter: saturate(0.15) brightness(0.82);
		}
	}
	.cv-hero__inner {
		display: flex;
		position: relative;
	}
	#cv-name {
		margin: 0 0 25px;
		font:
			300 clamp(64px, 7.6vw, 112px) / 0.98 "Outfit",
			sans-serif;
		letter-spacing: -0.055em;
		span {
			color: #d9b974;
		}
	}
	.cv-hero__role {
		font:
			400 clamp(15px, 1.35vw, 20px) / 1.5 "Outfit",
			sans-serif;
		margin: 0 0 25px;
	}
	.cv-hero__intro {
		font:
			300 clamp(22px, 2.25vw, 30px) / 1.35 "Outfit",
			sans-serif;
		letter-spacing: -0.4px;
		margin: 0 0 18px;
	}
	.cv-hero__summary {
		font:
			300 16px/1.75 "Outfit",
			sans-serif;
		max-width: 430px;
		margin: 0 0 30px;
		color: #d1d3cc;
	}
	.cv-actions {
		display: flex;
		flex-wrap: wrap;
	}
	.cv-button {
		display: inline-flex;
		align-items: center;
		justify-content: center;
		border: 1px solid #777362;
		min-height: 52px;
		transition:
			background 0.2s,
			color 0.2s,
			border-color 0.2s;
	}
	.cv-button--solid {
		color: #10120d;
		background: #e2c88d;
		border-color: #e2c88d;
	}
	.cv-button:hover {
		color: #10120d;
		background: #f3f1eb;
		border-color: #f3f1eb;
	}
	.cv-hero__links {
		display: flex;
		flex-wrap: wrap;
		gap: 12px 25px;
		margin-top: 23px;
		font-size: 12px;
		color: #d1d3cc;
	}
	.cv-hero__links {
		a {
			min-height: 30px;
			display: inline-flex;
			align-items: center;
			&:hover {
				color: var(--cv-gold);
			}
		}
	}
	.cv-hero__caption {
		position: absolute;
		bottom: 130px;
		right: 0;
		color: #eee0c7;
		font:
			300 13px/1.5 "Outfit",
			sans-serif;
		letter-spacing: 0.05em;
	}
	.cv-hero__foot {
		display: flex;
		gap: 20px;
		position: absolute;
		left: 0;
		right: 0;
		color: var(--cv-muted);
		font:
			400 10px/1.6 "Outfit",
			sans-serif;
		letter-spacing: 0.12em;
		text-transform: uppercase;
		a span {
			margin-left: 18px;
		}
	}
	.cv-nav {
		position: sticky;
		z-index: 100;
		background: rgba(9, 12, 11, 0.96);
		backdrop-filter: blur(16px);
		border-block: 1px solid var(--cv-line);
	}
	.cv-nav {
		.cv-wrap {
			display: flex;
			align-items: center;
		}
		a {
			display: flex;
			align-items: center;
			color: #919b91;
			font:
				400 11px/1.5 "Outfit",
				sans-serif;
			border-bottom: 2px solid transparent;
			transition:
				color 0.3s,
				border-color 0.3s;
			span {
				color: var(--cv-text);
			}
		}
	}
	.cv-nav a[aria-current],
	.cv-nav a:hover {
		border-color: var(--cv-gold);
		color: var(--cv-gold);
	}
	.cv-nav .cv-nav__pdf {
		color: var(--cv-gold);
	}
	.cv-section {
		border-bottom: 1px solid var(--cv-line);
	}
	.cv-section__label {
		align-self: start;
	}
	.cv-section h2 {
		font:
			300 clamp(26px, 2.7vw, 38px) / 1.2 "Outfit",
			sans-serif;
		letter-spacing: -0.8px;
		margin: 0 0 23px;
	}
	.cv-lead {
		font:
			300 20px/1.8 "Outfit",
			sans-serif;
		margin: 0;
		color: #d2d5ce;
	}
	.cv-facts {
		display: grid;
		grid-template-columns: repeat(3, 1fr);
		margin: 40px 0 0;
		padding-top: 30px;
		border-top: 1px solid var(--cv-line);
	}
	.cv-facts {
		dt {
			font:
				300 clamp(30px, 3.2vw, 46px) / 1.2 "Outfit",
				sans-serif;
			color: var(--cv-gold);
			letter-spacing: -1px;
			margin-bottom: 10px;
		}
		dd {
			color: var(--cv-muted);
			font:
				400 12px/1.7 "Outfit",
				sans-serif;
			margin: 0;
			max-width: 145px;
		}
	}
	.cv-aside-note {
		color: var(--cv-muted);
		font:
			300 14px/1.8 "Outfit",
			sans-serif;
		margin: 0 0 25px;
	}
	.cv-text-link {
		display: inline-block;
		font:
			400 13px/1.7 "Outfit",
			sans-serif;
		color: var(--cv-gold);
		padding: 6px 0;
		border-bottom: 1px solid #776644;
		&:hover {
			color: #f3f1eb;
			border-color: #f3f1eb;
		}
	}
	.cv-timeline {
		border-left: 1px solid var(--cv-line);
	}
	.cv-role {
		position: relative;
		padding-bottom: 45px;
		margin-bottom: 40px;
		border-bottom: 1px solid var(--cv-line);
		&::before {
			content: "";
			position: absolute;
			top: 5px;
			width: 9px;
			height: 9px;
			border: 1px solid var(--cv-gold);
			border-radius: 50%;
			background: var(--cv-bg);
		}
	}
	.cv-role--lead::before {
		background: var(--cv-gold);
		box-shadow: 0 0 18px #d9b97444;
	}
	.cv-role__period {
		color: var(--cv-gold);
		font:
			400 12px/1.7 "Outfit",
			sans-serif;
		margin: 0 0 16px;
		display: flex;
		flex-wrap: wrap;
		gap: 8px 20px;
		span {
			color: var(--cv-muted);
			font-size: 10px;
			text-transform: uppercase;
			letter-spacing: 0.12em;
		}
	}
	.cv-role h3 {
		font:
			400 27px/1.3 "Outfit",
			sans-serif;
		letter-spacing: -0.5px;
		margin: 0 0 8px;
	}
	.cv-role__company {
		color: #d2d5ce;
		font:
			300 18px/1.5 "Outfit",
			sans-serif;
		margin: 0 0 24px;
	}
	.cv-role {
		ul {
			margin: 0;
			padding-left: 18px;
			color: var(--cv-muted);
		}
		li {
			padding-left: 5px;
			font:
				300 16px/1.8 "Outfit",
				sans-serif;
			margin-bottom: 11px;
			&::marker {
				color: #9b8657;
				font-size: 9px;
			}
		}
		.cv-text-link {
			margin-top: 15px;
		}
	}
	.cv-earlier {
		h3 {
			font:
				400 22px/1.4 "Outfit",
				sans-serif;
			margin: 0 0 30px;
		}
		article {
			margin-bottom: 26px;
		}
		.cv-role__period {
			margin-bottom: 7px;
		}
		h4 {
			font:
				400 18px/1.5 "Outfit",
				sans-serif;
			margin: 0;
		}
		article > p:last-child {
			color: var(--cv-muted);
			font:
				300 15px/1.7 "Outfit",
				sans-serif;
			margin: 2px 0;
		}
	}
	.cv-skills {
		article {
			display: flex;
			padding: 25px 0;
			border-bottom: 1px solid var(--cv-line);
			&:first-child {
				padding-top: 0;
			}
			&:last-child {
				border-bottom: 0;
				padding-bottom: 0;
			}
		}
	}
	.cv-skill-index {
		color: var(--cv-gold);
		font-size: 11px;
		padding-top: 5px;
	}
	.cv-skills {
		h3 {
			font:
				400 21px/1.4 "Outfit",
				sans-serif;
			margin: 0 0 10px;
		}
		p {
			color: var(--cv-muted);
			font:
				300 16px/1.8 "Outfit",
				sans-serif;
			margin: 0;
		}
	}
	.cv-education {
		article + article {
			margin-top: 40px;
			padding-top: 35px;
			border-top: 1px solid var(--cv-line);
		}
		h3 {
			font:
				400 25px/1.4 "Outfit",
				sans-serif;
			margin: 0 0 12px;
		}
		article > p:last-child {
			color: var(--cv-muted);
			font:
				300 17px/1.7 "Outfit",
				sans-serif;
			margin: 0;
		}
	}
	.cv-grade {
		display: inline-block;
		margin-left: 15px;
		border: 1px solid #685d40;
		padding: 3px 9px;
		font-size: 12px;
		color: var(--cv-gold);
	}
	.cv-interests {
		h2 {
			font:
				300 clamp(28px, 4vw, 46px) / 1.25 "Outfit",
				sans-serif;
			margin: 0 0 26px;
			letter-spacing: -1px;
		}
		ul {
			display: flex;
			flex-wrap: wrap;
			gap: 12px 30px;
			padding: 0;
			margin: 0;
			list-style: none;
			color: var(--cv-muted);
			font-size: 16px;
		}
	}
	.cv-contact {
		display: grid;
		align-items: center;
		border-top: 1px solid var(--cv-line);
		background: radial-gradient(
			ellipse at 25% 100%,
			#b3934912,
			transparent 65%
		);
	}
	.cv-contact {
		h2 {
			font:
				300 clamp(32px, 4vw, 52px) / 1.1 "Outfit",
				sans-serif;
			letter-spacing: -1.5px;
			margin: 0;
		}
		p:not(.cv-kicker) {
			color: var(--cv-muted);
			font:
				300 18px/1.7 "Outfit",
				sans-serif;
		}
	}
	.cv-contact__email {
		font-size: 17px;
		overflow-wrap: anywhere;
	}
	.cv-contact .cv-actions {
		margin-top: 25px;
	}
}
