/* Workspace navigation uses shared geometry and states with each workspace palette. */
body.dxbus-page .dxbus-app {
	--workspace-nav-accent: var(--dxbus-active);
	--workspace-nav-text: #bfc6ca;
	--workspace-nav-hover-text: #f1f0e8;
	--workspace-nav-hover: #ffffff0d;
	--workspace-nav-selected: #f42e3b1c;
	--workspace-nav-selected-text: #ffafb4;
	--workspace-bar: var(--dxbus-canvas);
	--workspace-bar-border: var(--dxbus-line);
}

body.dxgym-page {
	overflow-x: clip;

	#dxgym-app {
		--workspace-nav-accent: var(--gym-accent);
		--workspace-nav-text: var(--gym-secondary);
		--workspace-nav-hover-text: var(--gym-text);
		--workspace-nav-hover: var(--gym-hover);
		--workspace-nav-selected: color-mix(
			in srgb,
			var(--gym-accent) 18%,
			var(--gym-page)
		);
		--workspace-nav-selected-text: var(--gym-text);
		--workspace-bar: var(--gym-page);
		--workspace-bar-border: var(--gym-line);
	}
}

body.dxcp-page .dxcp-shell {
	--workspace-nav-accent: var(--dxcp-link);
	--workspace-nav-text: var(--dxcp-muted);
	--workspace-nav-hover-text: var(--dxcp-ink);
	--workspace-nav-hover: var(--dxcp-soft);
	--workspace-nav-selected: var(--dxcp-selected);
	--workspace-nav-selected-text: var(--dxcp-selected-ink);
	--workspace-bar: var(--dxcp-canvas);
	--workspace-bar-border: var(--dxcp-line);
}

body:is(.dxbus-page, .dxgym-page, .dxcp-page)
	:is(.dxbus-app, #dxgym-app, .dxcp-shell)
	:is(.dxbus-sidebar, .dxgym-sidebar, .dxcp-sidebar)
	nav {
	display: grid;
	gap: 4px;
	min-height: 0;
	overflow-y: auto;
	overscroll-behavior: contain;

	> a {
		display: flex;
		align-items: center;
		min-height: 44px;
		padding: 8px 10px;
		gap: 8px;
		border: 0;
		border-radius: 0;
		color: var(--workspace-nav-text);
		font-size: 13px;
		line-height: 1.35;
		text-decoration: none;
		transition:
			color 0.2s ease,
			background-color 0.2s ease,
			box-shadow 0.2s ease;

		svg {
			width: 18px;
			height: 18px;
		}

		&:is(:hover, :focus-visible) {
			background: var(--workspace-nav-hover);
			color: var(--workspace-nav-hover-text);
		}

		&:is([aria-current], [aria-selected="true"]) {
			background: var(--workspace-nav-selected);
			color: var(--workspace-nav-selected-text);
			box-shadow: inset 3px 0 var(--workspace-nav-accent);
			font-weight: 500;

			svg {
				color: var(--workspace-nav-accent);
			}
		}

		@media (min-width: 992px) and (max-height: 850px) {
			min-height: 38px;
		}
	}
}

body.dxcp-page .dxcp-shell .dxcp-sidebar nav > a.dxcp-nav-link {
	color: var(--workspace-nav-text) !important;
	&:is(:hover, :focus-visible) {
		color: var(--workspace-nav-hover-text) !important;
	}
	&[aria-current] {
		color: var(--workspace-nav-selected-text) !important;
	}
}

body.dxgym-page #dxgym-app .dxgym-mobile-nav a[aria-current] {
	color: var(--workspace-nav-accent);
}

body:is(.dxbus-page, .dxgym-page, .dxcp-page)
	:is(.dxbus-app, #dxgym-app, .dxcp-shell)
	:is(
		.dxbus-sidebar nav,
		.dxgym-sidebar nav,
		.dxcp-sidebar nav,
		.dxgym-mobile-nav
	)
	> a:focus-visible {
	outline: 2px solid var(--workspace-nav-accent);
	outline-offset: -2px;
}

@media (prefers-reduced-motion: reduce) {
	body:is(.dxbus-page, .dxgym-page, .dxcp-page)
		:is(.dxbus-app, #dxgym-app, .dxcp-shell)
		:is(.dxbus-sidebar nav, .dxgym-sidebar nav, .dxcp-sidebar nav)
		> a {
		transition: none;
	}
}

