/* * * General */

html {
	overflow-x: hidden;
}

@mixin dx-conventional-footer {
	footer {
		background-color: #fff;

		&.site-footer {
			background: #000;
			color: rgba(255, 255, 255, 0.85);
			padding: 5rem 2rem 2rem;
			font-size: 0.875rem;
			line-height: 1.6;
			z-index: 2;
			position: relative;

			a {
				color: inherit;
				text-decoration: none;
				transition: opacity 0.2s ease;

				&:hover,
				&:focus {
					opacity: 1;
				}
			}

			/* Brand */

			.site-footer-brand {
				text-align: center;
				margin-bottom: 4rem;
			}

			.site-footer-logo {
				font-size: 1.25rem;
				font-weight: 500;
				letter-spacing: 0.04em;
			}

			/* Columns */

			.site-footer-columns {
				display: grid;
				width: 100%;
				row-gap: 4rem;
				grid-template-columns: 1fr;
				gap: 3rem;

				@include respond-from(640.02px) {
					grid-template-columns: repeat(2, 1fr);
				}

				@include respond-from(1024.02px) {
					grid-template-columns: repeat(5, minmax(0, 1fr));
					row-gap: 3rem;
				}
			}

			.site-footer-column {
				display: flex;
				flex-direction: column;
				gap: 1rem;
			}

			.site-footer-column-portal {
				gap: 1.25rem;
			}

			/* Headings */

			.site-footer-heading {
				font-size: 22px;
				font-weight: 500;
				margin: 0 0 0.5rem;
			}

			.site-footer-subheading {
				color: white;
				margin: 1.5rem 0 0.25rem;
			}

			/* Menus */

			.site-footer-list {
				list-style: none;
				padding: 0;
				margin: 0;
				display: flex;
				flex-direction: column;
				gap: 4px;

				li {
					margin: 0.35rem 0;
				}

				a {
					opacity: 0.7;

					&:hover {
						opacity: 1;
					}
				}
			}

			/* Portal CTA */

			.site-footer-button {
				display: inline-flex;
				align-items: center;
				justify-content: center;
				padding: 0.75rem 1.5rem;
				border: 1px solid rgba(255, 255, 255, 0.6666);
				border-radius: 2px;
				background: transparent;
				transition:
					background 0.2s ease,
					color 0.2s ease;

				&:hover,
				&:focus {
					background: #fff;
					color: #000;
				}
			}

			.site-footer-text {
				opacity: 0.7;
				max-width: 260px;
			}

			.site-footer-contact {
				a {
					padding: 4px 0;
				}
			}

			/* Bottom bar */

			.site-footer-bottom {
				margin-top: 4rem;
				padding-top: 2rem;
				border-top: 1px solid rgba(255, 255, 255, 0.1);
				grid-template-columns: 1fr;
				text-align: center;

				@include media-breakpoint-up(md) {
					grid-template-columns: 1fr auto 1fr;
					text-align: start;
					gap: 1rem;
				}
			}

			.site-footer-legal {
				@include media-breakpoint-up(md) {
					justify-content: normal;
				}

				a {
					opacity: 0.6666;

					&:hover {
						opacity: 1;
					}
				}
			}

			.site-footer-copyright {
				opacity: 0.6;
			}

			.site-footer-social {
				display: flex;
				gap: 1.25rem;

				@include media-breakpoint-up(md) {
					justify-content: flex-end;
				}

				a {
					font-size: 2em;

					&:hover {
						opacity: 1;
					}
				}
			}
		}
	}
}

