			.enquiry-review {
				padding: 20px;
				border: 1px solid #493a23;
				margin: 16px 0;

				h2 {
					font-size: 22px;
					font-weight: 300;
				}

				p {
					margin: 12px 0;
					line-height: 1.6;
				}

				strong,
