			.enquiry-privacy,
			.enquiry-alternative {
				font-size: 13px;
				color: #bcb7af;
			}

			.enquiry-alternative {
				text-align: center;
				margin-top: 25px;
			}

			.enquiry-error {
				color: #ffc5aa;
				padding: 12px;
				border: 1px solid #805c42;
			}

			.enquiry-trap {
				position: absolute;
				left: -10000px;
				width: 1px;
				height: 1px;
				overflow: hidden;
			}

			.enquiry-status {
				margin: 12px 0 0;
				font-size: 13px;
			}

			.enquiry-success {
