	&.page-template-page-legal {
		#main {
			margin-top: 150px;

			> .content {
				overflow: hidden;
				color: white;

				.legal-banner {
					padding: 2em 0;
				}

				.legal-content {
					--legal-panel: #101010;
					--legal-header: #171717;
					--legal-cell: #121212;
					--legal-border: #303030;
					--legal-text: #eee;
					--legal-muted: #bbb;
					--legal-accent: #bb0000;

					p {
						font-weight: 300;
					}

					a {
						font-weight: 300;
						color: white;
						border-bottom: 1px solid rgba(255, 255, 255, 0.5);
						transition:
							color 0.2s ease,
							border-color 0.2s ease;

						&:hover {
							border-bottom-color: white;
						}

						&:focus-visible {
							outline: 2px solid white;
							outline-offset: 3px;
						}

						@media (prefers-reduced-motion: reduce) {
							transition: none;
						}
					}

					#cmplz-document {
						/* Prevent the plugin's focus styles shifting links.*/

						a:focus {
							padding: 0;
							border: 0;
							outline: 2px solid white;
							outline-offset: 3px;
						}

						/* Cookie service accordions*/

						.cmplz-dropdown.cmplz-dropdown-cookiepolicy {
							margin: 0 0 16px;
							padding: 0;
							background: var(--legal-panel);
							color: var(--legal-text);
							border: 1px solid #292929;
							box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
							border-radius: 10px;

							@include media-breakpoint-up(md) {
								border-radius: 12px;
							}

							> summary.cmplz-service-header {
								margin: 0;
								background: var(--legal-header);
								color: white;
								cursor: pointer;
								padding: 18px;
								border-radius: 9px;

								@include media-breakpoint-up(md) {
									padding: 22px 24px;
									border-radius: 11px;
								}

								&:hover {
									background: #202020;
								}

								&:focus-visible {
									outline: 2px solid white;
									outline-offset: 4px;
								}

								> div {
									column-gap: 8px;
									row-gap: 8px;
									grid-template-areas: "heading heading label checkbox chevron" "paragraph paragraph paragraph paragraph chevron";
									grid-template-columns: minmax(0, 1fr) auto 0 auto 20px;

									@include media-breakpoint-up(md) {
										column-gap: 15px;
										row-gap: 15px;
										grid-template-areas: "heading paragraph label checkbox chevron";
										grid-template-columns: 2fr auto 0 auto 25px;
									}

									&::after {
										width: 14px;
										height: 14px;
										filter: brightness(0) invert(1);
										opacity: 0.7;

										@media (prefers-reduced-motion: reduce) {
											transition: none;
										}
									}
								}

								h3 {
									margin: 0;
									padding: 0;
									color: white;
									font-family: inherit;
									font-weight: 500;
									letter-spacing: -0.02em;
									line-height: 1.4;
									overflow-wrap: anywhere;
									font-size: 17px;

									@include media-breakpoint-up(md) {
										font-size: 18px;
									}
								}

								p {
									box-sizing: border-box;
									max-width: 100%;
									margin: 0;
									padding: 5px 10px;
									background: #252525;
									color: #ccc;
									border: 1px solid #3a3a3a;
									border-radius: 6px;
									font-size: 12px;
									font-weight: 400;
									line-height: 1.5;
									overflow-wrap: anywhere;
									justify-self: start;
									text-align: left;

									@include media-breakpoint-up(md) {
										justify-self: end;
										text-align: center;
									}
								}
							}

							&[open] > summary.cmplz-service-header {
								border-bottom: 1px solid var(--legal-border);
								box-shadow: inset 3px 0 0 var(--legal-accent);
								border-radius: 9px 9px 0 0;

								@include media-breakpoint-up(md) {
									border-radius: 11px 11px 0 0;
								}

								> div::after {
									opacity: 1;
								}
							}

							> .cmplz-service-description,
							> .cmplz-sharing-data {
								box-sizing: border-box;
								background: transparent;
								vertical-align: top;
								display: block;
								width: 100%;
								padding: 20px 18px;

								@include media-breakpoint-up(md) {
									display: inline-block;
									width: calc(50% - 4px);
									padding: 28px 24px;
								}

								h4 {
									margin: 0 0 10px;
									padding: 0;
									color: #aaa;
									font-size: 11px;
									font-weight: 500;
									letter-spacing: 0.12em;
									line-height: 1.5;
									text-transform: uppercase;
								}

								p {
									margin: 0;
									padding: 0;
									color: #ccc;
									font-size: 14px;
									line-height: 1.8;
									overflow-wrap: anywhere;
								}
							}

							> .cmplz-sharing-data {
								padding-top: 0;

								@include media-breakpoint-up(md) {
									padding-top: 28px;
								}
							}

							a {
								color: var(--legal-text);
								border-bottom: 0;
								text-decoration: underline;
								text-decoration-color: #666;
								text-decoration-thickness: 1px;
								text-underline-offset: 4px;
								overflow-wrap: anywhere;

								&:hover {
									color: white;
									text-decoration-color: white;
								}

								&[target="_blank"]::after {
									filter: brightness(0) invert(1);
									opacity: 0.65;
								}
							}

							/* Cookie tables*/

							> .cookies-per-purpose {
								min-width: 0;
								gap: 0;
								background: var(--legal-cell);
								border: 1px solid var(--legal-border);
								border-radius: 8px;
								margin: 0 12px 16px;
								grid-template: none;
								grid-template-columns: minmax(0, 90px) minmax(
										0,
										1fr
									);

								@include media-breakpoint-up(md) {
									grid-template-columns:
										minmax(0, 1.25fr) minmax(0, 0.75fr)
