				/* ========================================================= CHAPTER SELECTOR ========================================================= */

				.chapter-selector {
					position: fixed;
					z-index: 20;
					opacity: 0;
					pointer-events: none;
					justify-content: center;
					display: flex;
					text-align: center;
					transition:
						opacity 0.4s ease,
						transform 0.4s ease;

					@include media-breakpoint-up(lg) {
						bottom: auto;
						transform: translateY(-50%) translateX(-8px);
					}

					@include media-breakpoint-up(lg) {
						width: auto;
						top: 50%;
						left: 2rem;
						height: auto;
						max-height: 70vh;
						overflow-y: auto;
					}

					/* transform: translateY(-50%) translateX(-8px);*/

					&::after {
						content: "";
						position: absolute;
						top: 0;
						left: 0;
						width: 100%;
						height: 100%;
						background-image: linear-gradient(
							180deg,
							rgba(0, 0, 0, 0),
							#000000
						);
						opacity: 0.75;
						z-index: -1;
						pointer-events: none;
						transition: 0.3s all ease;

						@include media-breakpoint-up(lg) {
							opacity: 0;
						}
					}

					ul {
						list-style: none;
						flex-wrap: nowrap;
						overflow-x: auto;
						max-width: 100%;

						@include media-breakpoint-up(lg) {
							flex-direction: column;
							justify-content: center;
							left: 2rem;
						}
					}

					a {
						align-items: center;
						min-height: 44px;

						&:focus-visible {
							outline: 2px solid white;
							outline-offset: 2px;
						}
					}

					li {
						&:focus-within {
							opacity: 1;
						}

						& {
							flex-shrink: 0;
							cursor: pointer;
							opacity: 0.35;
							display: flex;
							gap: 0;
							align-items: center;
							transition: opacity 0.3s ease;

							@include media-breakpoint-up(sm) {
								gap: 1.5em;
							}

							span {
								font-size: 0.75rem;
								letter-spacing: 0.12em;
								text-transform: uppercase;
								color: #fff;
								white-space: nowrap;
								line-height: 20px;
							}

							&:hover {
								opacity: 0.7;
							}

							&.is-active {
								opacity: 1;
							}

							&::before {
								content: "";
								width: 1px;
								height: 24px;
								background-color: transparent;
							}
						}
					}
				}

				/* ========================================================= CHAPTER PROGRESS BAR ========================================================= */

				.chapter-progress {
					position: absolute;
					left: -6px;
					top: 0;
					height: 100%;
					width: 2px;
					background: rgba(255, 255, 255, 0.15);
					overflow: hidden;
					display: none;

					@include media-breakpoint-up(lg) {
						display: block;
					}

					span {
						display: block;
						width: 100%;
						height: 100%;
						background: white;
						transform-origin: top;
						transform: scaleY(0);
						transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
					}
				}

				/* ========================================================= GLOBAL SCROLL OFFSET ========================================================= */

				.wp-block-heading {
					scroll-margin-top: 120px;
				}
			}

			.chapter-selector {
				flex-direction: column;
				gap: 0.75rem;

				.chapter-step-controls {
					display: flex;
					justify-content: space-between;
					gap: 0.75rem;

					button {
						min-height: 44px;
