	&.single-gym-review {
		--gym-bg: #050505;
		--gym-bg-soft: #080807;
		--gym-panel: #0b0b0a;
		--gym-panel-raised: #10100e;
		--gym-panel-warm: #13100b;
		--gym-text: #f5f2ea;
		--gym-text-soft: #d6d1c6;
		--gym-muted: #9d988e;
		--gym-muted-dark: #726e66;
		--gym-gold: #d9ad5b;
		--gym-gold-light: #efca83;
		--gym-gold-pale: #f4ddad;
		--gym-gold-dark: #8f672f;
		--gym-positive: #d9ad5b;
		--gym-negative: #bd644b;
		--gym-neutral: #8c8981;
		--gym-border: rgba(217, 173, 91, 0.22);
		--gym-border-strong: rgba(217, 173, 91, 0.44);
		--gym-border-neutral: rgba(255, 255, 255, 0.08);
		--gym-shadow: 0 28px 80px rgba(0, 0, 0, 0.48);
		--gym-container: 1440px;
		background: var(--gym-bg);
		color: var(--gym-text);
		/* ============================================================*/
		/* TOKENS*/
		/* ============================================================*/
		/* ============================================================*/
		/* PAGE WRAPPER / SHARED*/
		/* ============================================================*/

		.gym-review-single {
			position: relative;
			overflow: clip;
			background: var(--gym-bg);
			color: var(--gym-text);

			* {
				box-sizing: border-box;
			}

			img {
				max-width: 100%;
				height: auto;
			}

			a {
				color: inherit;
				text-decoration: none;
			}

			.container {
				width: calc(100% - 30px);
				margin-inline: auto;

				@include media-breakpoint-up(md) {
					width: min(var(--gym-container), calc(100% - 48px));
				}

				@include media-breakpoint-up(xl) {
					width: min(var(--gym-container), calc(100% - 80px));
				}
			}

			*,
			*::before,
			*::after {
				@media (prefers-reduced-motion: reduce) {
					scroll-behavior: auto !important;
					animation-duration: 0.01ms !important;
					animation-iteration-count: 1 !important;
					transition-duration: 0.01ms !important;
				}
			}
		}

		/* ============================================================*/
		/* SHARED TYPOGRAPHY*/
		/* ============================================================*/

		.gym-review-kicker {
			display: flex;
			align-items: center;
			gap: 14px;
			margin: 0 0 20px;
			color: var(--gym-gold);
			font-size: 0.64rem;
			font-weight: 600;
			line-height: 1;
			letter-spacing: 0.24em;
			text-transform: uppercase;

			@include media-breakpoint-up(md) {
				margin-bottom: 26px;
				font-size: 0.72rem;
			}

			&::after {
				content: "";
				width: 48px;
				height: 1px;
				background: var(--gym-border-strong);
			}
		}

		.gym-review-section-heading {
			display: flex;
			flex-direction: column;
			align-items: flex-start;
			gap: 12px;
			margin-bottom: 28px;

			@include media-breakpoint-up(md) {
				flex-direction: row;
				justify-content: space-between;
				gap: 40px;
				margin-bottom: 36px;
			}

			.gym-review-kicker {
				margin-bottom: 0;
			}

			small {
				color: var(--gym-muted);
				font-size: 0.75rem;
				line-height: 1.5;
				text-align: left;

				@include media-breakpoint-up(md) {
					text-align: right;
				}
			}
		}

		/* ============================================================*/
		/* HERO*/
		/* ============================================================*/

		.gym-review-hero {
			position: relative;
			display: flex;
			align-items: flex-end;
			min-height: 740px;
			overflow: hidden;
			isolation: isolate;
			border-bottom: 1px solid var(--gym-border);

			@include media-breakpoint-up(md) {
				min-height: 760px;
			}

			@include media-breakpoint-up(xl) {
				min-height: min(860px, 92vh);
			}

			&::after {
				content: "";
				position: absolute;
				z-index: 1;
				inset: auto 0 0;
				height: 180px;
				background: linear-gradient(
					to bottom,
					transparent,
					var(--gym-bg)
				);
				pointer-events: none;
			}

			&__media {
				position: absolute;
				z-index: -3;
				inset: 0;
				overflow: hidden;
			}

			&__image {
				position: absolute;
				inset: 0;
				display: block;
				width: 100%;
				height: 100%;
				max-width: none;
				max-height: none;
				object-fit: cover;
				object-position: 50% 50%;
				transform: scale(1.035);
				will-change: transform;
				filter: saturate(0.9) contrast(1.05) brightness(0.9);
			}

			&__overlay {
				position: absolute;
				z-index: -2;
				inset: 0;
				background: linear-gradient(
					to top,
					rgba(2, 2, 2, 0.98) 0%,
					rgba(2, 2, 2, 0.78) 42%,
					rgba(2, 2, 2, 0.23) 78%
				);

				@include media-breakpoint-up(md) {
					background: radial-gradient(
							circle at 75% 35%,
							rgba(216, 165, 74, 0.08),
							transparent 30%
						),
						linear-gradient(
							90deg,
							rgba(2, 2, 2, 0.97) 0%,
							rgba(2, 2, 2, 0.86) 27%,
							rgba(2, 2, 2, 0.46) 53%,
							rgba(2, 2, 2, 0.09) 78%
						),
						linear-gradient(
							0deg,
							rgba(2, 2, 2, 0.94) 0%,
							rgba(2, 2, 2, 0.3) 42%,
							rgba(2, 2, 2, 0.14) 100%
						);
				}
			}

			&__content {
				position: relative;
				z-index: 2;
				width: 100%;
				padding-top: 150px;
				padding-bottom: 75px;

				@include media-breakpoint-up(md) {
					padding-top: 170px;
					padding-bottom: 90px;
				}

				@include media-breakpoint-up(xl) {
					padding-top: 190px;
					padding-bottom: 100px;
				}
			}

			&__eyebrow {
				display: flex;
				flex-direction: column;
				align-items: flex-start;
				gap: 8px;
				margin-bottom: 30px;
				color: var(--gym-gold);
				font-size: 0.72rem;
				font-weight: 600;
				line-height: 1;
				letter-spacing: 0.28em;
				text-transform: uppercase;

				span {
					color: var(--gym-gold);
				}

				strong {
					color: var(--gym-text);
					font-size: 0.9rem;
					font-weight: 500;
				}
			}

			&__title {
				max-width: 100%;
				margin: 0;
				color: var(--gym-text);
				font-size: clamp(3.7rem, 17vw, 5.8rem);
				font-weight: 300;
				line-height: 0.86;
				letter-spacing: -0.06em;
				text-wrap: balance;
				text-transform: uppercase;

				@include media-breakpoint-up(md) {
					max-width: 780px;
					font-size: clamp(4rem, 10vw, 7rem);
					line-height: 0.82;
				}

				@include media-breakpoint-up(xl) {
					font-size: clamp(4.5rem, 8vw, 8.8rem);
				}
			}

			&__location {
				display: flex;
				align-items: center;
				gap: 10px;
				margin-top: 25px;
				color: var(--gym-text-soft);
				font-size: 0.82rem;

				@include media-breakpoint-up(md) {
					margin-top: 32px;
					font-size: 0.92rem;
				}

				span,
				svg {
					color: var(--gym-gold);
				}
			}

			/* ------------------------------------------------------------*/
			/* BACK TO REVIEWS*/
			/* ------------------------------------------------------------*/

			.gym-review-back {
				display: inline-flex;
				align-items: center;
				gap: 10px;
				margin-bottom: 26px;
				color: var(--gym-text-soft);
				font-size: 0.62rem;
				font-weight: 600;
				letter-spacing: 0.16em;
				text-transform: uppercase;
				transition: color 220ms ease;

				@include media-breakpoint-up(md) {
					margin-bottom: 34px;
					font-size: 0.68rem;
				}

				&__arrow {
					display: inline-flex;
					align-items: center;
					justify-content: center;
					width: 28px;
					height: 28px;
					border: 1px solid var(--gym-border-strong);
					border-radius: 50%;
					color: var(--gym-gold-light);
					font-size: 0.9rem;
					line-height: 1;
					transition:
						background 220ms ease,
						color 220ms ease,
						transform 220ms ease;

					@include media-breakpoint-up(md) {
						width: 30px;
						height: 30px;
					}
				}

				&:hover {
					color: var(--gym-gold-light);

					.gym-review-back__arrow {
						background: var(--gym-gold);
						color: var(--gym-bg);
						transform: translateX(-3px);
					}
				}
			}

			/* ------------------------------------------------------------*/
			/* RATING*/
			/* ------------------------------------------------------------*/

			.gym-review-rating {
				display: flex;
				flex-wrap: wrap;
				align-items: flex-end;
				gap: 16px;
				margin-top: 30px;

				@include media-breakpoint-up(sm) {
					flex-wrap: nowrap;
				}

				@include media-breakpoint-up(md) {
					align-items: center;
					gap: 26px;
					margin-top: 38px;
				}

				&__number {
					display: block;
					color: var(--gym-gold-light);
					font-size: 3.9rem;
					font-weight: 400;
					line-height: 0.9;
					letter-spacing: -0.045em;
					font-variant-numeric: tabular-nums;

					@include media-breakpoint-up(md) {
						font-size: clamp(3.8rem, 5vw, 6.5rem);
					}
				}

				&__status {
					display: inline-flex;
					align-items: center;
					gap: 10px;
					padding-bottom: 5px;
					color: var(--gym-gold-light);
					font-size: 0.65rem;
					font-weight: 600;
					letter-spacing: 0.18em;
					text-transform: uppercase;

					@include media-breakpoint-up(md) {
						padding-bottom: 0;
						font-size: 0.75rem;
					}

					&::before {
						content: "✦";
						display: inline-grid;
						place-items: center;
						width: 26px;
						height: 26px;
						border: 1px solid var(--gym-border-strong);
						border-radius: 50%;
						color: var(--gym-gold);

						@include media-breakpoint-up(md) {
							width: 30px;
							height: 30px;
						}
					}
				}
			}

			/* ------------------------------------------------------------*/
			/* BADGES*/
			/* ------------------------------------------------------------*/

			.gym-review-badges {
				display: flex;
				flex-wrap: wrap;
				gap: 10px;
				margin-top: 28px;

				.gym-review-badge {
					display: inline-flex;
					align-items: center;
					justify-content: center;
					min-height: 34px;
					padding: 7px 15px;
					border: 1px solid var(--gym-border-strong);
					border-radius: 999px;
					background: rgba(14, 11, 6, 0.38);
					backdrop-filter: blur(14px);
					color: var(--gym-gold-light);
					font-size: 0.58rem;
					font-weight: 600;
					letter-spacing: 0.14em;
					text-transform: uppercase;

					@include media-breakpoint-up(md) {
						font-size: 0.63rem;
					}
				}
			}
		}

		/* ============================================================*/
		/* QUICK FACTS*/
		/* ============================================================*/

		.gym-review-facts {
			position: relative;
			z-index: 5;
			border-bottom: 1px solid var(--gym-border);
			background: #070706;

			&__grid {
				display: grid;
				grid-template-columns: 1fr;

				@include media-breakpoint-up(sm) {
					grid-template-columns: repeat(2, 1fr);
				}

				@include media-breakpoint-up(lg) {
					grid-template-columns: repeat(3, 1fr);
				}

				@include media-breakpoint-up(xl) {
					grid-template-columns: repeat(5, minmax(0, 1fr));
				}
			}

			.gym-review-fact {
				position: relative;
				display: flex;
				flex-direction: column;
				justify-content: center;
				min-height: 96px;
				padding: 20px 16px;
				border-right: 0;
				border-bottom: 1px solid var(--gym-border-neutral);

				@include media-breakpoint-up(sm) {
					border-right: 1px solid var(--gym-border-neutral);
				}

				@include media-breakpoint-up(md) {
					min-height: 110px;
					padding: 24px 32px;
				}

				@include media-breakpoint-up(xl) {
					border-bottom: 0;
				}

				&::before {
					content: "";
					position: absolute;
					top: 0;
					left: 0;
					width: 0;
					height: 1px;
					background: var(--gym-gold);
					transition: width 350ms ease;
				}

				&:hover {
					background: rgba(217, 173, 91, 0.025);

					&::before {
						width: 100%;
					}
				}

				span {
					display: block;
					margin-bottom: 9px;
					color: var(--gym-muted);
					font-size: 0.61rem;
					font-weight: 500;
					letter-spacing: 0.18em;
					text-transform: uppercase;
				}

				strong {
					display: block;
					color: var(--gym-text);
					font-size: 0.9rem;
					font-weight: 500;
					line-height: 1.4;
				}

				&:nth-child(2n) {
					@include media-breakpoint-up(sm) {
						border-right: 0;
					}

					@include media-breakpoint-up(lg) {
						border-right: 1px solid var(--gym-border-neutral);
					}
				}

				&:nth-child(3n) {
					@include media-breakpoint-up(lg) {
						border-right: 0;
					}

					@include media-breakpoint-up(xl) {
						border-right: 1px solid var(--gym-border-neutral);
					}
				}

				&:last-child {
					@include media-breakpoint-up(xl) {
						border-right: 0;
					}
				}
			}
		}

		/* ============================================================*/
		/* VERDICT / LOCATION*/
		/* ============================================================*/

		.gym-review-overview {
			position: relative;
			padding: 68px 0;
			border-bottom: 1px solid var(--gym-border);

			@include media-breakpoint-up(md) {
				padding: 82px 0;
			}

			@include media-breakpoint-up(xl) {
				padding: 96px 0;
			}

			&::before {
				content: "";
				position: absolute;
				inset: 0;
				background: radial-gradient(
					circle at 0 50%,
					rgba(180, 119, 38, 0.055),
					transparent 35%
				);
				pointer-events: none;
			}

			&__grid {
				position: relative;
				display: grid;
				grid-template-columns: 1fr;
				gap: 0;

				@include media-breakpoint-up(xl) {
					grid-template-columns: minmax(0, 0.88fr) minmax(0, 1.12fr);
				}
			}

			.gym-review-verdict {
				padding: 0 0 45px;
				border-bottom: 1px solid var(--gym-border);

				@include media-breakpoint-up(xl) {
					padding: 0 72px 0 0;
					border-right: 1px solid var(--gym-border);
					border-bottom: 0;
				}

				&__lead {
					max-width: 620px;
					color: var(--gym-text);
					font-size: 1.55rem;
					font-weight: 300;
					line-height: 1.36;
					letter-spacing: -0.025em;

					@include media-breakpoint-up(md) {
						font-size: clamp(1.65rem, 2.3vw, 2.6rem);
					}

					p {
						margin: 0 0 26px;

						&:last-child {
							margin-bottom: 0;
						}
					}
				}

				&__notes {
					max-width: 670px;
					margin-top: 32px;
					color: var(--gym-muted);
					font-size: 0.97rem;
					line-height: 1.8;
				}
			}

			.gym-review-location {
				padding-top: 45px;

				@include media-breakpoint-up(xl) {
					padding: 0 0 0 72px;
				}

				.gym-review-section-heading {
					margin-bottom: 28px;
				}

				.gym-review-map {
					position: relative;
					width: 100%;
					height: 300px;
					overflow: hidden;
					border: 1px solid var(--gym-border);
					background: #0c0c0b;

					@include media-breakpoint-up(md) {
						height: 360px;
					}

					&::after {
						content: "";
						position: absolute;
						z-index: 2;
						inset: 0;
						box-shadow: inset 0 0 80px rgba(0, 0, 0, 0.42);
						pointer-events: none;
					}

					iframe {
						width: 100%;
						height: 100%;
						border: 0;
						filter: grayscale(1) invert(0.9) contrast(1.15)
							brightness(0.72) sepia(0.12);
						transform: scale(1.01);
					}

					&__loading {
						position: absolute;
						inset: 0;
						display: grid;
						place-items: center;
						color: var(--gym-muted);
						font-size: 0.75rem;
						letter-spacing: 0.12em;
						text-transform: uppercase;
					}
				}

				&__address {
					display: grid;
					grid-template-columns: 1fr;
					align-items: center;
					gap: 15px;
					padding: 20px 0;
					border-bottom: 1px solid var(--gym-border-neutral);

					@include media-breakpoint-up(md) {
						grid-template-columns: 1fr auto;
						gap: 24px;
					}

					> div {
						display: flex;
						flex-direction: column;
						gap: 6px;
					}

					strong {
						color: var(--gym-text);
						font-size: 0.92rem;
						font-weight: 500;
					}

					span {
						color: var(--gym-muted);
						font-size: 0.8rem;
						line-height: 1.5;
					}
				}

				&__directions {
					display: inline-flex;
					align-items: center;
					gap: 12px;
					color: var(--gym-gold-light);
					font-size: 0.72rem;
					font-weight: 600;
					letter-spacing: 0.1em;
					text-transform: uppercase;
					transition:
						color 220ms ease,
						transform 220ms ease;

					&:hover {
						color: var(--gym-text);
						transform: translateX(3px);
					}
				}
			}
		}

		/* ============================================================*/
		/* SCORES*/
		/* ============================================================*/

		.gym-review-scores {
			padding: 68px 0;
			border-bottom: 1px solid var(--gym-border);

			@include media-breakpoint-up(xl) {
				padding: 92px 0;
			}

			&__grid {
				display: grid;
				grid-template-columns: 1fr;
				gap: 14px 20px;

				@include media-breakpoint-up(md) {
					grid-template-columns: repeat(2, minmax(0, 1fr));
				}
			}

			.gym-review-score {
				position: relative;
				padding: 21px 18px;
				overflow: hidden;
				border: 1px solid var(--gym-border-neutral);
				background: linear-gradient(
					110deg,
					rgba(217, 173, 91, 0.045),
					rgba(255, 255, 255, 0.008) 46%,
					transparent
				);
				transition:
					border-color 250ms ease,
					background 250ms ease,
					transform 250ms ease;

				@include media-breakpoint-up(md) {
					padding: 23px 24px 24px;
				}

				&::before {
					content: "";
					position: absolute;
					top: 0;
					left: 0;
					width: 2px;
					height: 0;
					background: var(--gym-gold);
					transition: height 350ms ease;
				}

				&:hover {
					border-color: var(--gym-border);
					background: linear-gradient(
						110deg,
						rgba(217, 173, 91, 0.075),
						rgba(255, 255, 255, 0.012) 50%,
						transparent
					);
					transform: translateY(-2px);

					&::before {
						height: 100%;
					}
				}

				&__meta {
					display: flex;
					align-items: center;
					justify-content: space-between;
					gap: 20px;
					margin-bottom: 17px;

					span {
						color: var(--gym-text-soft);
						font-size: 0.86rem;
						font-weight: 500;
					}

					strong {
						color: var(--gym-gold-light);
						font-size: 0.86rem;
						font-weight: 600;
						font-variant-numeric: tabular-nums;
					}
				}

				&__track {
					position: relative;
					width: 100%;
					height: 4px;
					overflow: hidden;
					background: rgba(255, 255, 255, 0.1);
				}

				&__fill {
					position: absolute;
					inset: 0 auto 0 0;
					width: 0;
					background: linear-gradient(
						90deg,
						var(--gym-gold-dark),
						var(--gym-gold),
						var(--gym-gold-light)
					);
					box-shadow: 0 0 18px rgba(217, 173, 91, 0.22);
					transition: width 1100ms cubic-bezier(0.22, 1, 0.36, 1);
				}

				&.is-unavailable {
					opacity: 0.4;

					.gym-review-score__fill {
						display: none;
					}
				}
			}
		}

		/* ============================================================*/
		/* LIKES / DISLIKES / FACILITIES*/
		/* ============================================================*/

		.gym-review-breakdown {
			padding-bottom: 68px;
			border-bottom: 1px solid var(--gym-border);

			@include media-breakpoint-up(xl) {
				padding-bottom: 90px;
			}

			&__grid {
				display: grid;
				grid-template-columns: 1fr;
				align-items: stretch;

				@include media-breakpoint-up(md) {
					grid-template-columns: repeat(2, 1fr);
				}

				@include media-breakpoint-up(xl) {
					grid-template-columns: 1fr 1fr 1.12fr;
				}
			}

			.gym-review-panel {
				position: relative;
				min-height: auto;
				padding: 34px 26px;
				overflow: hidden;
				border: 1px solid var(--gym-border);
				border-bottom: 0;
				background: var(--gym-panel);

				@include media-breakpoint-up(md) {
					min-height: 430px;
					padding: 42px;
				}

				@include media-breakpoint-up(xl) {
					border-right: 0;
					border-bottom: 1px solid var(--gym-border);
				}

				&:last-child {
					border-bottom: 1px solid var(--gym-border);

					@include media-breakpoint-up(xl) {
						border-right: 1px solid var(--gym-border);
					}
				}

				&::before {
					content: "";
					position: absolute;
					inset: 0;
					background: radial-gradient(
						circle at 10% 100%,
						rgba(217, 173, 91, 0.08),
						transparent 45%
					);
					pointer-events: none;
				}

				> * {
					position: relative;
					z-index: 1;
				}

				h2 {
					display: flex;
					align-items: center;
					gap: 17px;
					margin: 0 0 32px;
					padding-bottom: 20px;
					border-bottom: 1px solid var(--gym-border-neutral);
					color: var(--gym-gold-light);
					font-size: 0.72rem;
					font-weight: 600;
					letter-spacing: 0.18em;
					text-transform: uppercase;

					span {
						color: var(--gym-gold);
						font-size: 1.4rem;
						font-weight: 300;
						line-height: 1;
					}
				}

				ul {
					display: grid;
					gap: 18px;
					margin: 0;
					padding: 0;
					list-style: none;
				}

				li {
					position: relative;
					padding-left: 30px;
					color: var(--gym-text-soft);
					font-size: 0.9rem;
					line-height: 1.45;
				}

				&--likes {
					@include media-breakpoint-up(md) {
						border-right: 0;
					}

					li {
						&::before {
							content: "✓";
							position: absolute;
							top: 0;
							left: 0;
							color: var(--gym-positive);
							font-weight: 600;
						}
					}
				}

				&--dislikes {
					background: linear-gradient(
						145deg,
						rgba(66, 24, 16, 0.15),
						var(--gym-panel) 48%
					);

					@include media-breakpoint-up(md) {
						border-right: 1px solid var(--gym-border);
					}

					@include media-breakpoint-up(xl) {
						border-right: 0;
					}

					li {
						&::before {
							content: "—";
							position: absolute;
							top: 0;
							left: 0;
							color: var(--gym-negative);
							font-weight: 600;
						}
					}
				}

				&--facilities {
					background: linear-gradient(
						145deg,
						rgba(217, 173, 91, 0.035),
						var(--gym-panel) 50%
					);

					@include media-breakpoint-up(md) {
						grid-column: 1 / -1;
					}

					@include media-breakpoint-up(md) {
						border-top: 0;
						border-right: 1px solid var(--gym-border);
					}

					@include media-breakpoint-up(xl) {
						grid-column: auto;
					}

					.gym-review-facilities {
						display: grid;
						grid-template-columns: repeat(2, 1fr);
						gap: 9px;

						@include media-breakpoint-up(md) {
							grid-template-columns: repeat(3, minmax(0, 1fr));
						}

						.gym-review-facility {
							position: relative;
							display: flex;
							flex-direction: column;
							align-items: center;
							justify-content: center;
							gap: 10px;
							min-height: 94px;
							padding: 13px 8px;
							border: 1px solid var(--gym-border-neutral);
							background: rgba(255, 255, 255, 0.012);
							text-align: center;
							transition:
								border-color 220ms ease,
								background 220ms ease,
								transform 220ms ease;

							&:hover {
								border-color: var(--gym-border);
								background: rgba(217, 173, 91, 0.03);
								transform: translateY(-2px);
							}

							&__indicator {
								width: 7px;
								height: 7px;
								border-radius: 50%;
							}

							strong {
								color: var(--gym-text-soft);
								font-size: 0.68rem;
								font-weight: 500;
								line-height: 1.35;
							}

							&--available {
								.gym-review-facility__indicator {
									background: var(--gym-positive);
									box-shadow: 0 0 12px rgba(217, 173, 91, 0.4);
								}
							}

							&--limited {
								.gym-review-facility__indicator {
									background: var(--gym-neutral);
								}
							}

							&--unavailable {
								opacity: 0.42;

								.gym-review-facility__indicator {
									background: var(--gym-negative);
								}
							}
						}
					}
				}
			}
		}

		/* ============================================================*/
		/* GALLERY*/
		/* ============================================================*/

		.gym-review-gallery {
			padding: 65px 0;
			border-bottom: 1px solid var(--gym-border);

			@include media-breakpoint-up(xl) {
				padding: 82px 0 92px;
			}

			&__viewport {
				position: relative;
				width: calc(100vw - 15px);
				overflow-x: auto;
				scrollbar-width: none;
				scroll-snap-type: x mandatory;
				-webkit-overflow-scrolling: touch;

				@include media-breakpoint-up(md) {
					width: 100%;
					overflow: hidden;
					scroll-snap-type: none;
				}

				&::-webkit-scrollbar {
					display: none;
				}
			}

			&__track,
			&__grid {
				display: flex;
				gap: 10px;

				@include media-breakpoint-up(md) {
					display: grid;
					grid-template-columns: repeat(2, minmax(0, 1fr));
					gap: 12px;
				}

				@include media-breakpoint-up(xl) {
					grid-template-columns: repeat(4, minmax(0, 1fr));
				}
			}

			figure {
				position: relative;
				flex: 0 0 82vw;
				height: 320px;
				margin: 0;
				overflow: hidden;
				cursor: zoom-in;
				background: var(--gym-panel);
				scroll-snap-align: start;

				@include media-breakpoint-up(md) {
					flex: initial;
					height: 285px;
					scroll-snap-align: none;
				}

				&::after {
					content: "";
					position: absolute;
					inset: 0;
					background: linear-gradient(
						to top,
						rgba(0, 0, 0, 0.28),
						transparent 45%
					);
					opacity: 0;
					transition: opacity 400ms ease;
				}

				&:hover {
					&::after {
						opacity: 1;
					}

					img {
						transform: scale(1.045);
						filter: brightness(1.07) saturate(1.05);
					}
				}
			}

			img {
				width: 100%;
				height: 100%;
				object-fit: cover;
				transition:
					transform 750ms cubic-bezier(0.22, 1, 0.36, 1),
					filter 750ms ease;
			}

			&__controls {
				display: flex;
				align-items: center;
				justify-content: center;
				gap: 10px;
				margin-top: 20px;
			}

			&__dot {
				width: 25px;
				height: 2px;
				padding: 0;
				border: 0;
				background: rgba(255, 255, 255, 0.16);
				transition:
					width 220ms ease,
					background 220ms ease;

				&.is-active {
					width: 42px;
					background: var(--gym-gold);
				}
			}
		}

		/* ============================================================*/
		/* FULL REVIEW*/
		/* ============================================================*/

		.gym-review-content {
			position: relative;
			padding: 72px 0;

			@include media-breakpoint-up(xl) {
				padding: 100px 0;
			}

			&::before {
				content: "";
				position: absolute;
				inset: 0;
				background: radial-gradient(
					circle at 100% 20%,
					rgba(217, 173, 91, 0.05),
					transparent 34%
				);
				pointer-events: none;
			}

			&__grid {
				position: relative;
				display: grid;
				grid-template-columns: 1fr;
				align-items: start;
				gap: 45px;

				@include media-breakpoint-up(md) {
					gap: 60px;
				}

				@include media-breakpoint-up(xl) {
					grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
					gap: 90px;
				}
			}

			&__body {
				max-width: 100%;
				color: var(--gym-text-soft);
				font-size: 0.95rem;
				line-height: 1.78;

				@include media-breakpoint-up(md) {
					max-width: 780px;
					font-size: 1rem;
					line-height: 1.85;
				}

				@include media-breakpoint-up(xl) {
					max-width: 680px;
				}

				p {
					margin: 0 0 25px;
				}

				h2,
				h3,
				h4 {
					margin: 48px 0 18px;
					color: var(--gym-text);
					font-weight: 400;
					letter-spacing: -0.02em;
				}

				h2 {
					font-size: 2rem;
				}

				h3 {
					font-size: 1.5rem;
				}

				ul,
				ol {
					padding-left: 1.4rem;
					color: var(--gym-text-soft);
				}

				a {
					color: var(--gym-gold-light);
					text-decoration: underline;
					text-decoration-color: var(--gym-border-strong);
					text-underline-offset: 4px;
				}

				blockquote {
					margin: 42px 0;
					padding: 8px 0 8px 28px;
					border-left: 2px solid var(--gym-gold);
					color: var(--gym-text);
					font-size: 1.35rem;
					font-weight: 300;
					line-height: 1.6;
				}
			}

			&__image {
				position: relative;
				top: auto;
				height: 470px;
				margin: 0;
				overflow: hidden;
				border: 1px solid var(--gym-border-neutral);
				box-shadow: var(--gym-shadow);

				@include media-breakpoint-up(md) {
					height: 600px;
				}

				@include media-breakpoint-up(xl) {
					position: sticky;
					top: 120px;
					height: 680px;
				}

				img {
					width: 100%;
					height: 100%;
					object-fit: cover;
				}
			}
		}

		/* ============================================================*/
		/* FINAL VERDICT*/
		/* ============================================================*/

		.gym-review-final {
			position: relative;
			padding: 85px 0 95px;
			overflow: hidden;
			border-top: 1px solid var(--gym-border);
			text-align: center;

			@include media-breakpoint-up(xl) {
				padding: 110px 0 120px;
			}

			&::before {
				content: "";
				position: absolute;
				top: 50%;
				left: 50%;
				width: 650px;
				height: 650px;
				border-radius: 50%;
				background: radial-gradient(
					circle,
					rgba(217, 173, 91, 0.07),
					transparent 67%
				);
				transform: translate(-50%, -50%);
				pointer-events: none;
			}

			.container {
				position: relative;
			}

			.gym-review-kicker {
				justify-content: center;

				&::after {
					display: none;
				}
			}

			&__score {
				display: block;
				color: var(--gym-gold-light);
				font-size: clamp(5rem, 24vw, 8rem);
				font-weight: 300;
				line-height: 0.92;
				letter-spacing: -0.06em;
				font-variant-numeric: tabular-nums;

				@include media-breakpoint-up(xl) {
					font-size: clamp(5.5rem, 11vw, 11rem);
				}
			}

			&__label {
				display: block;
				margin-top: 24px;
				color: var(--gym-gold);
				font-size: 0.8rem;
				font-weight: 600;
				letter-spacing: 0.25em;
				text-transform: uppercase;
			}
		}

		/* ============================================================*/
		/* PREVIOUS / NEXT*/
		/* ============================================================*/

		.gym-review-navigation {
			border-top: 1px solid var(--gym-border);
			background: #070706;

			&__grid {
				display: grid;
				grid-template-columns: 1fr;

				@include media-breakpoint-up(md) {
					grid-template-columns: repeat(2, minmax(0, 1fr));
				}
			}

			a {
				display: flex;
				flex-direction: column;
				justify-content: center;
				min-height: 130px;
				padding: 28px 15px;
				transition: background 250ms ease;

				@include media-breakpoint-up(md) {
					min-height: 180px;
					padding: 40px;
				}

				&:first-child {
					border-bottom: 1px solid var(--gym-border-neutral);

					@include media-breakpoint-up(md) {
						border-right: 1px solid var(--gym-border-neutral);
						border-bottom: 0;
					}
				}

				&:hover {
					background: rgba(217, 173, 91, 0.035);

					strong {
						color: var(--gym-gold-light);
					}
				}

				span {
					margin-bottom: 10px;
					color: var(--gym-muted);
					font-size: 0.62rem;
					letter-spacing: 0.16em;
					text-transform: uppercase;
				}

				strong {
					color: var(--gym-text);
					font-size: 1.15rem;
					font-weight: 400;
					transition: color 220ms ease;
				}
			}
		}

		/* ============================================================*/
		/* LIGHTBOX*/
		/* ============================================================*/

		.gym-review-lightbox {
			position: fixed;
			z-index: 99999;
			inset: 0;
			display: flex;
			align-items: center;
			justify-content: center;
			padding: 50px 15px;
			background: rgba(0, 0, 0, 0.94);
			backdrop-filter: blur(15px);
			opacity: 0;
			visibility: hidden;
			transition:
				opacity 260ms ease,
				visibility 260ms ease;

			@include media-breakpoint-up(md) {
				padding: 70px;
			}

			&.is-open {
				opacity: 1;
				visibility: visible;
			}

			&__image {
				display: block;
				max-width: min(1400px, 92vw);
				max-height: 84vh;
				object-fit: contain;
				box-shadow: 0 40px 100px rgba(0, 0, 0, 0.7);
			}

			&__close,
			&__prev,
			&__next {
				position: absolute;
				display: grid;
				place-items: center;
				width: 42px;
				height: 42px;
				padding: 0;
				border: 1px solid var(--gym-border-strong);
				border-radius: 50%;
				background: rgba(0, 0, 0, 0.48);
				color: var(--gym-text);
				font-size: 1.25rem;
				cursor: pointer;
				transition:
					background 220ms ease,
					border-color 220ms ease,
					color 220ms ease;

				@include media-breakpoint-up(md) {
					width: 48px;
					height: 48px;
				}

				&:hover {
					border-color: var(--gym-gold);
					background: var(--gym-gold);
					color: #050505;
				}
			}

			&__close {
				top: 15px;
				right: 15px;

				@include media-breakpoint-up(md) {
					top: 26px;
					right: 26px;
				}
			}

			&__prev {
				top: 50%;
				left: 12px;
				transform: translateY(-50%);

				@include media-breakpoint-up(md) {
					left: 26px;
				}
			}

			&__next {
				top: 50%;
				right: 12px;
				transform: translateY(-50%);

				@include media-breakpoint-up(md) {
					right: 26px;
				}
			}
		}

		&.gym-lightbox-open {
			overflow: hidden;
		}

		/* ============================================================*/
		/* SCROLL REVEALS*/
		/* ============================================================*/

		[data-gym-reveal] {
			opacity: 0;
			transform: translateY(28px);
			transition:
				opacity 900ms ease-in-out,
				transform 900ms cubic-bezier(0.25, 0.46, 0.45, 0.94);

			&.is-visible {
				opacity: 1;
				transform: translateY(0);
			}

			@media (prefers-reduced-motion: reduce) {
				opacity: 1;
				transform: none;
			}
		}

		/* ============================================================*/
		/* REDUCED MOTION*/
		/* ============================================================*/
	}

	&.page-buses,
	&.single-bus-diary-entry {
		#main {
			max-width: 100%;

			.bus-nfs-archive {
				position: relative;
				height: 100vh;
				min-height: 720px;
				overflow: hidden;
				background: #020202;
				color: white;

				&__topbar {
					position: absolute;
					top: 48px;
					left: 50%;
					z-index: 20;
					width: min(90vw, 1200px);
					transform: translateX(-50%);
					display: flex;
					justify-content: space-between;
