					.gym-archive[data-view="list"] {
						.dx-gyms-grid {
							display: grid;
							gap: 12px;
							grid-template-columns: repeat(1, 1fr);
						}

						.dx-gym-card {
							display: grid;
							grid-template-columns: 1fr;
							/* whatever “list” style means for you:*/
