					/* ========================================================= GRID + LIST VIEW ========================================================= */

					.dx-gyms-grid {
						display: grid;
						gap: 1.25rem;
						margin-top: 2rem;

						@include media-breakpoint-up(md) {
							grid-template-columns: repeat(2, 1fr);
							gap: 1.5rem;
						}

						@include media-breakpoint-up(xl) {
							grid-template-columns: repeat(3, 1fr);
						}
					}

					.gym-archive.is-list-view {
						.dx-gyms-grid {
							grid-template-columns: 1fr !important;
						}

						.dx-gym-card {
							padding: 1.5rem;
						}
					}

					/* ========================================================= CARD ========================================================= */

					.dx-gym-card {
						background: rgba(255, 255, 255, 0.03);
						border: 1px solid rgba(255, 255, 255, 0.06);
						padding: 2rem;
						display: flex;
						flex-direction: column;
						gap: 1.25rem;
						transition: 0.35s ease;

						&:hover {
							background: rgba(255, 255, 255, 0.05);
							transform: translateY(-3px);
						}
					}

					.dx-gym-card__header {
						display: flex;
						flex-direction: column;
						gap: 0.75rem;
					}

					.dx-gym-card__subtitle {
						margin-bottom: 0.5rem;
						font-size: 0.8rem;
						letter-spacing: 0.14em;
						text-transform: uppercase;
						color: rgba(255, 255, 255, 0.65);
						line-height: 1.3;

						a {
							color: inherit;
							padding-bottom: 4px;
							text-decoration: none;
							border-bottom: 1px solid rgba(255, 255, 255, 0.25);
							transition: 0.25s ease;

							&:hover {
								color: white;
								border-bottom: 1px solid white;
							}
						}
					}

					.dx-gym-card__branch {
						margin: 0;
						font-size: 1.25rem;

						a {
							color: white;
						}
					}

					.dx-gym-card__meta {
						display: flex;
						flex-wrap: wrap;
						gap: 0.5rem;
					}

					.dx-badge {
						font-size: 0.7rem;
						padding: 0.4rem 0.75rem;
						border-radius: 999px;
						background: rgba(255, 255, 255, 0.08);
						display: inline-flex;
						align-items: center;
						gap: 0.4rem;

						&--category {
							border: 1px solid rgba(102, 255, 224, 0.35);
							background: rgba(102, 255, 224, 0.08);
							color: #9fffea;
							text-transform: uppercase;
							letter-spacing: 1px;
							font-size: 0.625rem;
						}

						&--best {
							border: 1px solid #ffac34;
							text-transform: uppercase;
							letter-spacing: 2px;
							font-size: 0.625em;
							color: gold;
							background: #ffcc4e42;
						}

						&--worst {
							border: 1px solid #e95354;
							text-transform: uppercase;
							letter-spacing: 2px;
							font-size: 0.625em;
							color: #d6b7af;
							background: rgb(191 105 83 / 35%);
						}

						&--overall {
							border: 1px solid rgba(255, 255, 255, 0.12);

							&.is-good {
								.text,
								.emoji {
									color: #8be28b;
								}
							}

							&.is-mid {
								.text,
								.emoji {
									color: #d2b48c;
								}
							}

							&.is-bad {
								.text,
								.emoji {
									color: #ff6b6b;
								}
							}

							&.is-unrated {
								.text,
								.emoji {
									color: rgba(255, 255, 255, 0.55);
								}
							}
						}

						&--overall[data-score="na"] {
							opacity: 0.65;
						}

						/* Overall heat colouring */

						&--overall[data-score="0"] {
							color: #ff3b3b;
						}

						&--overall[data-score="1"] {
							color: #ff4b4b;
						}

						&--overall[data-score="2"] {
							color: #ff5a5a;
						}

						&--overall[data-score="3"] {
							color: #ff7070;
						}

						&--overall[data-score="4"] {
							color: #ff8a8a;
						}

						&--overall[data-score="5"] {
							color: rgba(255, 255, 255, 0.95);
						}

						&--overall[data-score="6"] {
							color: #d8ffd8;
						}

						&--overall[data-score="7"] {
							color: #b8ffb8;
						}

						&--overall[data-score="8"] {
							color: #7dff7d;
						}

						&--overall[data-score="9"] {
							color: #4dff9f;
						}

						&--overall[data-score="10"] {
							color: #66ffe0;
						}
					}

					/* ========================================================= SCORES + ANIMATED BARS ========================================================= */

					.dx-gym-card__scores {
						display: grid;
						gap: 0.85rem;
					}

					.dx-score-block {
						display: grid;
						gap: 0.4rem;

						.dx-score-top {
							display: flex;
							justify-content: space-between;
							gap: 1rem;
							font-size: 0.9rem;
						}

						.dx-score-label {
							opacity: 0.85;
							font-weight: 300;
						}

						.dx-score-value {
							font-weight: 600;
						}

						.dx-score-bar {
							height: 6px;
							background: rgba(255, 255, 255, 0.08);
							overflow: hidden;

							span {
								display: block;
								height: 100%;
								width: 100%;
								transform-origin: left;
								transform: scaleX(0);
								transition: transform 650ms
									cubic-bezier(0.2, 0.8, 0.2, 1);
								background: currentColor;
								opacity: 0.9;
								will-change: transform;
							}
						}

						/* animate in on load */
						/* .dx-score-bar span { transform: scaleX(var(--pct, 0)); }*/

						&.is-unavailable,
						&.is-didnt-use {
							color: rgba(255, 255, 255, 0.45);

							.dx-score-value {
								font-weight: 300;
							}
						}

						/* score colour mapping (0–10) */

						&[data-score="0"] {
							color: #ff3b3b;
						}

						&[data-score="1"] {
							color: #ff4b4b;
						}

						&[data-score="2"] {
							color: #ff5a5a;
						}

						&[data-score="3"] {
							color: #ff7070;
						}

						&[data-score="4"] {
							color: #ff8a8a;
						}

						&[data-score="5"] {
							color: rgba(255, 255, 255, 0.95);
						}

						&[data-score="6"] {
							color: #d8ffd8;
						}

						&[data-score="7"] {
							color: #b8ffb8;
						}

						&[data-score="8"] {
							color: #7dff7d;
						}

						&[data-score="9"] {
							color: #4dff9f;
						}

						&[data-score="10"] {
							color: #66ffe0;
						}
					}

					/* ========================================================= NOTES ACCORDION ========================================================= */

					.dx-notes {
						border-top: 1px solid rgba(255, 255, 255, 0.06);
						padding-top: 1rem;
					}

					.dx-notes__toggle {
						width: 100%;
						display: inline-flex;
						justify-content: space-between;
						align-items: center;
						background: transparent;
						border: none;
						color: rgba(255, 255, 255, 0.85);
						padding: 0;
						cursor: pointer;
						font-size: 0.9rem;

						.chev {
							transition: transform 0.25s ease;
							opacity: 0.8;
