					}

					.dx-notes__panel {
						max-height: 0;
						overflow: hidden;
						opacity: 0.75;
						font-size: 0.85rem;
						line-height: 1.6;
						transition:
							max-height 0.35s ease,
							opacity 0.35s ease,
							margin-top 0.35s ease;
						margin-top: 0;
					}

					.dx-gym-card.is-notes-open {
						.dx-notes__panel {
							max-height: 240px;
							margin-top: 0.75rem;
							opacity: 0.9;
							/* enough for most notes; increase if you want*/
						}

						.dx-notes__toggle .chev {
							transform: rotate(180deg);
						}
					}

					.dx-notes__empty {
						opacity: 0.65;
					}

					/* ========================================================= PAGINATION ========================================================= */

					.gym-pagination {
						margin-top: 1.25rem;
						display: flex;
						justify-content: center;

						button {
							border-radius: 0;
							min-height: 56px;
							min-width: 220px;
							border: 1px solid rgba(255, 255, 255, 0.65);
							background: transparent;
							color: white;
							margin-top: 2em;
							transition: 0.25s ease;

							@include media-breakpoint-up(md) {
								margin-top: 3em;
							}

							&:hover {
								background: white;
								color: black;
								border-color: white;
							}
						}
					}
				}

				.tools {
					> .wp-block-group__inner-container {
						display: flex;
						flex-direction: column;
						/* gap: 32px;*/
					}

					.tool {
						p {
							font-size: 16px;
							font-weight: 300;
						}

						hr {
							margin: 0;
							height: 0;
							border: 0;
							border-top: 1px solid;
							border-image: linear-gradient(
