				width: 38px;
				height: 38px;
				line-height: 38px;
				background: #19150f;
				color: #eee8dc;
				border-color: #443b2e;

				&:hover {
					background: #302619;
				}

				&:focus-visible {
					outline: 2px solid #dbad67;
					outline-offset: -3px;
				}

				&.leaflet-disabled {
					color: #81796c;
				}
			}
		}

		.league-map-pin {
			display: grid;
			place-items: center;
			height: 30px;
			background: #15120e;
			border: 1px solid currentColor;
			border-radius: 5px;
			font-weight: 700;
		}

		.league-map-choices {
			display: grid;
			grid-template-columns: minmax(0, 1fr);
			gap: 0.5rem;
			max-height: 17rem;
			overflow-y: auto;
			padding: 1rem;
			border-top: 1px solid #332e28;
			scrollbar-width: thin;
			scrollbar-color: #655130 #100e0b;

			@include media-breakpoint-up(md) {
				grid-template-columns: repeat(2, minmax(0, 1fr));
			}

			.league-map-choice {
				display: flex;
				align-items: center;
				justify-content: space-between;
				gap: 0.75rem;
				min-width: 0;
				min-height: 64px;
				padding: 0.75rem 0.9rem;
				text-align: left;
				background: #14120e;
				color: #eee8dc;
				border: 1px solid #332e28;
				border-radius: 5px;
				transition:
					background 0.2s ease,
					border-color 0.2s ease;

				&:hover {
					background: #211b13;
					border-color: #655130;
				}

				&[aria-pressed="true"] {
					background: #2a2115;
					border-color: #dbad67;
				}

				&:focus-visible {
					outline: 2px solid #dbad67;
					outline-offset: 2px;
				}
			}
		}

		.league-map-choice-info {
			min-width: 0;

			strong {
				display: block;
				font-size: 0.85rem;
				line-height: 1.4;
				overflow-wrap: anywhere;
			}

			small {
				display: block;
				margin-top: 0.2rem;
				font-size: 0.7rem;
				color: #bcb7af;
			}
		}

		.league-map-choice-score {
			flex-shrink: 0;
			font-size: 0.95rem;
			font-weight: 600;
			font-variant-numeric: tabular-nums;
		}
	}

	&.page-services {
		#main {
			section.services {
				.featured-projects {
					.wp-block-post-template {
						display: grid;
						gap: 24px;
						padding: 0;
						list-style: none;
						align-items: stretch;
						grid-template-columns: minmax(0, 1fr);

						@include media-breakpoint-up(sm) {
							grid-template-columns: repeat(2, minmax(0, 1fr));
						}

						@include media-breakpoint-up(lg) {
							grid-template-columns: repeat(3, minmax(0, 1fr));
						}
					}

					li.type-service {
						min-width: 0;
						display: flex;
						flex-direction: column;
						padding: 0;
						margin: 0;
						background: linear-gradient(135deg, #12100c, #080807);
						transition:
							border-color 0.3s ease,
							box-shadow 0.3s ease;
						/* border: 1px solid rgba(213, 167, 78, .35);*/

						&:hover,
						&:focus-within {
							border-color: #d5a74e;
							box-shadow: 0 0 24px rgba(213, 167, 78, 0.08);
						}
					}

					.wp-block-post-featured-image {
						margin: 0;
						overflow: hidden;

						a {
							display: block;
						}

						img {
							display: block;
							width: 100%;
							height: auto;
							aspect-ratio: 16 / 10;
							object-fit: cover;
							transition: transform 0.6s
								cubic-bezier(0.22, 1, 0.36, 1);
						}
					}

					li.type-service:hover .wp-block-post-featured-image img {
						transform: scale(1.035);

						@media (prefers-reduced-motion: reduce) {
							transform: none;
						}
					}

					.project-info {
						width: 100%;
						flex: 1;
						margin: 0;

						> .wp-block-group__inner-container {
							height: 100%;
							display: flex;
							flex-direction: column;
							align-items: stretch;
						}
					}

					.service-card-category {
						display: flex;
						justify-content: space-between;
						gap: 12px;
						margin: 0 0 14px;
						color: #d5a74e;
						font:
							400 10px / 1.5 "Outfit",
							sans-serif;
						letter-spacing: 0.22em;
						text-transform: uppercase;
					}

					h3.wp-block-post-title,
					.service-training-card h3 {
						margin: 0 0 14px;
						font:
							300 clamp(23px, 1.9vw, 30px) / 1.15 "Outfit",
							sans-serif;
						letter-spacing: -0.015em;
						text-transform: uppercase;
						color: #f3f1eb;
					}

					.wp-block-post-excerpt {
						margin: 0 0 24px;
					}

					.wp-block-post-excerpt__excerpt,
					.service-training-content > p {
						margin: 0;
						font-size: 16px;
						font-weight: 300;
						line-height: 1.6;
						color: #d7d5cf;
					}

					.service-card-link {
						display: flex;
						justify-content: space-between;
						align-items: center;
						gap: 16px;
						min-height: 48px;
						padding-top: 16px;
						margin-top: auto;
						border-top: 1px solid rgba(213, 167, 78, 0.45);
						color: #d5a74e;
						font:
							400 11px / 1.5 "Outfit",
							sans-serif;
						letter-spacing: 0.17em;
						text-transform: uppercase;
						text-decoration: none;

						> span:last-child {
							font-size: 22px;
							letter-spacing: 0;
						}

						&:focus-visible {
							outline: 2px solid #d5a74e;
							outline-offset: 5px;
						}
					}

					.service-training-card {
						&.service-personal-card {
							grid-column: 1 / -1;
							grid-template-columns: 1fr;
							.service-training-content {
								grid-template-columns: 1fr 1.4fr;
								column-gap: 32px;
								> p,
								.service-card-link {
									max-width: none;
								}
								> .service-card-category {
									grid-column: 1 / -1;
									color: #d5ad63;
									font-size: 11px;
								}
								.service-card-link {
									grid-column: 2;
								}
								display: flex;
								@at-root {
									@include media-breakpoint-up(md) {
										body.is-frontend.page-services
											#main
											section.services
											.featured-projects
											.service-training-card.service-personal-card
											.service-training-content {
											display: grid;
										}
									}
								}
							}
						}
						grid-column: 1 / -1;
						display: grid;
						border: 1px solid rgba(213, 167, 78, 0.35);
						background: #0b0a08;
						overflow: hidden;
						grid-template-columns: minmax(0, 1fr);

						@include media-breakpoint-up(sm) {
							grid-template-columns: 1fr 1.5fr;
						}

						figure {
							margin: 0;
						}

						img {
							width: 100%;
							height: 100%;
							object-fit: cover;
							display: block;
							min-height: 0;
							aspect-ratio: 16 / 10;

							@include media-breakpoint-up(sm) {
								min-height: 280px;
								aspect-ratio: revert;
							}
						}
					}

					.service-training-content {
						display: flex;
						flex-direction: column;

						> p {
							margin-bottom: 24px;
							max-width: 580px;
						}
					}

					.service-training-heading {
						display: flex;
						gap: 16px;
						align-items: center;
						flex-wrap: wrap;
						margin-bottom: 18px;

						.service-card-category {
							margin: 0;
						}
					}

					.service-coming-soon {
						padding: 5px 12px;
						border: 1px solid #8e805f;
						border-radius: 999px;
						font-size: 10px;
						line-height: 1.5;
						letter-spacing: 0.14em;
						text-transform: uppercase;
						color: #e1d7bd;
					}

					.project-info,
					.service-training-content {
						padding: 24px;

						@include media-breakpoint-up(sm) {
							padding: 32px;
						}
					}

					li.type-service,
					.wp-block-post-featured-image img {
						@media (prefers-reduced-motion: reduce) {
							transition: none;
						}
					}
				}
			}
		}
	}

	&.league-sticky-ancestor:not(.nav-open) {
		@include media-breakpoint-up(lg) {
			overflow-x: clip !important;
			overflow-y: visible !important;
		}
	}

	:not(body).league-sticky-ancestor {
		@include media-breakpoint-up(lg) {
			overflow-x: clip !important;
			overflow-y: visible !important;
		}
	}
}

@keyframes league-diamond-glow {
	0%,
	100% {
		box-shadow:
			0 0 3px rgba(185, 234, 255, 0.3),
			0 0 7px rgba(185, 234, 255, 0.15);
	}

	50% {
		box-shadow:
			0 0 8px rgba(185, 234, 255, 0.75),
			0 0 18px rgba(185, 234, 255, 0.4);
	}
}

/* Scoring guide is mounted under body to avoid clipped or transformed page wrappers.*/

@keyframes league-zero-glow {
	0%,
	100% {
		background-color: #35101a;
		box-shadow: 0 0 3px rgba(140, 53, 75, 0.2);
	}

	50% {
		background-color: #8c354b;
		box-shadow:
			0 0 8px rgba(140, 53, 75, 0.65),
			0 0 16px rgba(140, 53, 75, 0.3);
	}
}

/* Early league placeholder, before JavaScript enhances the server-rendered reviews.*/

@keyframes league-placeholder-pulse {
	from {
		opacity: 0.35;
	}

	to {
		opacity: 0.75;
	}
}

/* A single flowing toolbar for discovery and view controls.*/

