			margin-top: 8px;
			padding-top: 12px;
			gap: 12px;
		}
		.dx-menu__navigation .dx-menu__list > .menu-item {
			min-height: 40px;
			> a {
				min-height: 40px;
				padding-top: 5px;
				padding-bottom: 5px;
			}
		}
		@include media-breakpoint-up(md) {
			.dx-menu__layout {
				min-height: 0;
			}
			.dx-menu__visual {
				position: fixed;
				inset: 0 0 0 50%;
				overflow: clip;
				contain: size;
			}
			.dx-menu__footer {
				flex-direction: row;
				align-items: flex-end;
				justify-content: space-between;
			}
			.dx-menu__navigation .dx-menu__list > .menu-item {
				min-height: clamp(40px, 5.4dvh, 65px);
