/* London by bus*/
body.dxb-page {
	background: #080807;
	background-image: none;
	color: #f3f1eb;
}
body.dxb-page {
	#main {
		padding: 0;
		max-width: none;
	}
	#wrapper {
		overflow: clip;
	}
	.dxb {
		--gold: #d5ad63;
		--line: rgba(208, 181, 128, 0.25);
		--muted: #b9b8b1;
		color: #f3f1eb;
		position: relative;
		isolation: isolate;
		font:
			400 16px/1.6 Outfit,
			sans-serif;
		padding-bottom: 0;
	}
}
.dxb {
	* {
		box-sizing: border-box;
	}
	[hidden] {
		display: none !important;
	}
	a {
		color: inherit;
		text-decoration: none;
	}
	button,
	input,
	select {
		font: inherit;
	}
	button,
	a,
	input,
	select,
	summary {
		touch-action: manipulation;
	}
	button {
		cursor: pointer;
	}
	:is(a, button, input, select, summary):focus-visible {
		outline: 2px solid #e7c684;
		outline-offset: 5px;
	}
}
.dxb-wrap {
	margin: auto;
}
.dxb-atmosphere {
	position: absolute;
	inset: 0 0 auto;
	height: 1500px;
	z-index: -2;
	background: radial-gradient(
			ellipse at 90% 37%,
			rgba(125, 75, 26, 0.3),
			transparent 58%
		),
		radial-gradient(
			ellipse at 0% 35%,
			rgba(18, 75, 75, 0.34),
			transparent 55%
		);
	pointer-events: none;
}
.dxb-hero-media {
	position: absolute;
	top: 0;
	left: 0;
	width: 100%;
	z-index: -1;
	mask-image: linear-gradient(#000 30%, transparent 100%);
	pointer-events: none;
	img {
		width: 100%;
		height: 100%;
		object-fit: cover;
		opacity: 0.65;
	}
	&:after {
		content: "";
		position: absolute;
		inset: 0;
		background: linear-gradient(
			90deg,
			rgba(4, 9, 10, 0.75),
			rgba(8, 8, 7, 0.08) 85%
		);
	}
}
.dxb-hero {
	padding: 170px 0 0;
}
.dxb {
	.dxb-eyebrow {
		font:
			400 10px/1.6 Outfit,
			sans-serif;
		letter-spacing: 0.2em;
		text-transform: uppercase;
		color: var(--gold);
		margin: 0 0 14px;
	}
	h1,
	h2,
	h3 {
		color: #f3f1eb;
		text-transform: none;
		font-family: Outfit, sans-serif;
		letter-spacing: -0.035em;
		line-height: 1.15;
		padding: 0;
	}
	h1 {
		font-weight: 200;
		text-transform: uppercase;
		margin: 0;
		max-width: 960px;
	}
	h2 {
		font-weight: 300;
		font-size: clamp(27px, 2.55vw, 38px);
		margin: 0 0 10px;
	}
	h3 {
		font-weight: 300;
		font-size: 24px;
		margin: 0 0 10px;
	}
	p {
		margin: 0 0 14px;
	}
}
.dxb-intro {
	margin: 22px 0 0 !important;
	color: #d2d0c9;
}
.dxb-nav {
	display: flex;
	overflow: auto;
	scrollbar-width: none;
	border: 1px solid transparent;
	border-bottom-color: var(--line);
	a {
		padding: 17px 0;
		white-space: nowrap;
		color: #d0cec9;
		border-bottom: 2px solid transparent;
	}
	a:hover,
	a[aria-current] {
		color: #e8c783;
		border-color: var(--gold);
	}
}
.dxb-panel {
	border: 1px solid var(--line);
	background: rgba(8, 8, 7, 0.75);
}
.dxb-explorer {
	display: grid;
	scroll-margin-top: 110px;
}
.dxb-explorer-main {
	min-width: 0;
}
.dxb-rule {
	height: 1px;
	background: linear-gradient(90deg, var(--gold), #403321);
	margin-bottom: 25px;
}
.dxb-muted {
	color: var(--muted);
}
.dxb-search {
	display: flex;
	position: relative;
	margin: 24px 0 18px;
	input {
		min-width: 0;
		padding: 12px 12px 12px 39px;
	}
}
.dxb {
	input,
	select {
		border: 1px solid var(--line);
		color: #f3f1eb;
		background: rgba(255, 255, 255, 0.025);
		border-radius: 0;
		min-height: 46px;
		outline-offset: 2px;
		color-scheme: dark;
	}
	input::placeholder {
		color: #aaa9a2;
	}
}
.dxb-search-icon {
	position: absolute;
	color: var(--gold);
	font-size: 22px;
}
.dxb-button {
	border: 1px solid #d5ad63;
	background: #d5ad63;
	color: #17130b;
	font-size: 13px;
	display: flex;
	align-items: center;
	&:hover {
		background: #ebcb91;
	}
}
.dxb-chips {
	display: flex;
	gap: 8px;
	flex-wrap: wrap;
}
.dxb-chips {
	button {
		min-height: 40px;
		min-width: 45px;
		padding: 8px 16px;
		background: transparent;
		color: #e3e0d8;
		border: 1px solid var(--line);
		font-size: 13px;
		&:hover {
			border-color: var(--gold);
		}
	}
	button[aria-pressed="true"] {
		background: #d5ad63;
		color: #17130b;
		border-color: #d5ad63;
	}
}
.dxb-status {
	color: var(--muted);
	font-size: 13px;
	margin: 18px 0 0 !important;
	min-height: 21px;
}
.dxb-status.is-error {
	color: #eac394;
}
.dxb-route-identity {
	display: flex;
	align-items: center;
	margin: 16px 0;
}
.dxb-route-identity {
	h3 {
		font-size: clamp(56px, 6vw, 88px);
		font-weight: 300;
		color: #eedabc;
		line-height: 1;
		margin: 0;
	}
	.dxb-eyebrow {
		margin: 0 0 4px;
	}
	p {
		font-size: 14px;
		margin: 0;
		color: var(--muted);
	}
}
.dxb-tabs {
	display: flex;
	overflow: auto;
	border-bottom: 1px solid var(--line);
	scrollbar-width: none;
}
.dxb-tabs {
	button {
		border: 0;
		border-bottom: 2px solid transparent;
		background: transparent;
		padding: 12px 0;
		color: #c9c6be;
		white-space: nowrap;
	}
	button[aria-selected="true"] {
		border-color: var(--gold);
		color: #e6c688;
	}
}
.dxb-tab-panel {
	padding: 20px 0 0;
	min-height: 125px;
}
.dxb-small {
	font-size: 12px;
	line-height: 1.65;
}
.dxb-details {
	margin: 20px 0 14px;
	border: 1px solid var(--line);
	padding: 10px 14px;
	font-size: 13px;
}
.dxb-details {
	summary {
		list-style: none;
		display: flex;
		justify-content: space-between;
		cursor: pointer;
		&::-webkit-details-marker {
			display: none;
		}
		span {
			color: var(--gold);
		}
	}
}
.dxb-details[open] summary {
	margin-bottom: 14px;
}
.dxb-text-button {
	background: none;
	border: 0;
	color: var(--gold);
	padding: 0;
	min-height: 32px;
	font-size: 12px !important;
}
.dxb-source {
	font-size: 10px;
	margin: 20px 0 0 !important;
	color: #99978f;
	a {
		color: #c8b487;
	}
}
.dxb-explorer-aside {
	position: relative;
	display: flex;
	flex-direction: column;
	overflow: hidden;
}
.dxb-explorer-aside {
	> div {
		position: relative;
		z-index: 2;
	}
	h2 {
		font:
			200 clamp(30px, 3vw, 46px) / 1.15 "Space Grotesk",
			sans-serif;
		letter-spacing: -0.025em;
	}
	figure {
		margin: 0;
		position: absolute;
		display: flex;
		align-items: flex-end;
		&:after {
			content: "";
			position: absolute;
			inset: 0;
		}
	}
	img {
		height: 100%;
		width: 100%;
		object-fit: cover;
		object-position: center;
	}
	figcaption {
		z-index: 2;
		position: absolute;
		bottom: 22px;
		right: 20px;
		color: #ddc494;
	}
}
.dxb-section {
	scroll-margin-top: 110px;
}
.dxb-section-heading {
	display: flex;
	justify-content: space-between;
	margin-bottom: 22px;
	h2 {
		margin-bottom: 0;
	}
}
.dxb-section-heading > a,
.dxb-link {
	color: var(--gold);
	font-size: 13px;
	white-space: nowrap;
}
.dxb-diary {
	display: grid;
}
.dxb-diary-photo {
	position: relative;
	overflow: hidden;
	display: flex;
	align-items: flex-end;
	& > img {
		position: absolute;
		inset: 0;
		width: 100%;
		height: 100%;
		object-fit: cover;
		transition: transform 0.5s;
	}
	&:after {
		content: "";
		position: absolute;
		inset: 0;
		background: linear-gradient(transparent 20%, rgba(0, 0, 0, 0.87));
	}
	> div {
		position: relative;
		z-index: 1;
	}
	h3 {
		font-size: 34px;
	}
	&:hover > img {
		transform: scale(1.025);
	}
}
.dxb-diary-notes {
	position: relative;
	overflow: hidden;
	background: radial-gradient(ellipse at 0% 100%, #12232680, transparent 70%);
}
.dxb-diary-notes {
	> p {
		font-size: 13px;
	}
	ol {
		list-style: none;
		margin: 28px 0 14px 28%;
		padding: 0;
		position: relative;
	}
	li {
		display: flex;
		gap: 14px;
		margin-bottom: 24px;
		& > span {
			color: var(--gold);
			font-size: 11px;
			border: 1px solid var(--line);
			width: 28px;
			height: 28px;
			display: grid;
			place-items: center;
			flex-shrink: 0;
		}
	}
	strong {
		font-weight: 400;
		font-size: 14px;
	}
	li p {
		font-size: 12px;
		line-height: 1.45;
		color: var(--muted);
		margin: 4px 0 0;
	}
}
.dxb-journey-trace {
	position: absolute;
	width: 33%;
	height: 250px;
	bottom: 22px;
	left: 0;
	opacity: 0.8;
	color: var(--gold);
	svg {
		height: 100%;
		width: 100%;
	}
}
.dxb-journey-list {
	display: grid;
	border: 1px solid var(--line);
	border-top: 0;
}
.dxb-journey-list {
	a {
		display: flex;
		align-items: center;
		gap: 16px;
		padding: 22px;
		font-size: 12px;
		&:last-child {
			border-right: 0;
		}
		&:hover {
			background: #d5ad630c;
		}
		& > span:last-child {
			margin-left: auto;
			color: var(--gold);
		}
	}
}
.dxb-journey-number {
	font-size: 26px;
	letter-spacing: -0.035em;
	color: #ead8b8;
}
.dxb-journey-list small {
	display: block;
	color: #94938c;
	margin-top: 6px;
}
.dxb-gallery-toolbar {
	display: flex;
	justify-content: space-between;
	margin-bottom: 20px;
	input {
		padding: 8px 13px;
		min-width: 245px;
	}
}
.dxb-gallery {
	display: grid;
}
.dxb-photo-card {
	border: 1px solid var(--line);
	min-width: 0;
	overflow: hidden;
	& > img {
		width: 100%;
		object-fit: cover;
		display: block;
		transition: transform 0.4s;
	}
	&:hover > img {
		transform: scale(1.035);
	}
	> div {
		position: relative;
		padding: 15px 18px;
	}
	.dxb-eyebrow {
		margin: 0 0 4px;
	}
	h3 {
		font-size: 17px;
		letter-spacing: -0.02em;
		padding-right: 20px;
		margin: 0;
	}
	> div > span:last-child {
		position: absolute;
		right: 18px;
		top: 24px;
		color: var(--gold);
	}
}
.dxb-editorial {
	display: grid;
	border-top: 1px solid var(--line);
	border-bottom: 1px solid var(--line);
	h2 {
		font-size: 29px;
	}
}
.dxb-editorial-empty {
	margin-top: 25px;
	border: 1px solid var(--line);
	padding: 25px;
	background: #d5ad6305;
}
.dxb-editorial-empty {
	h3 {
		font-size: 24px;
	}
	p {
		color: var(--muted);
		font-size: 14px;
	}
	a {
		font-size: 12px;
		color: var(--gold);
	}
}
.dxb-resource {
	display: flex;
	gap: 18px;
	padding: 22px 0;
	border-bottom: 1px solid var(--line);
}
.dxb-resource {
	> span {
		color: var(--gold);
		font-size: 12px;
	}
	> span:last-child {
		margin-left: auto;
		font-size: 18px;
	}
	h3 {
		font-size: 18px;
		letter-spacing: -0.015em;
		margin-bottom: 5px;
	}
	p {
		font-size: 12px;
		color: var(--muted);
		margin: 0;
	}
}
.dxb-editorial aside > .dxb-small {
	margin: 16px 0 0;
}
.dxb-article {
	display: flex;
	gap: 18px;
	align-items: center;
	border-bottom: 1px solid var(--line);
	padding: 22px 0;
	img {
		width: 110px;
		height: 90px;
		object-fit: cover;
	}
	h3 {
		font-size: 22px;
	}
	p {
		font-size: 13px;
		color: var(--muted);
	}
	> span {
		color: var(--gold);
	}
}
.dxb-signoff {
	display: flex;
	padding: 32px 0;
	color: #c4c0b7;
	align-items: center;
}
.dxb-signoff {
	> span {
		font-family: "Space Grotesk", sans-serif;
		font-weight: 500;
		letter-spacing: 0.05em;
		color: #f3f1eb;
	}
	p {
		margin: 0;
	}
	a {
		color: var(--gold);
	}
}
.dxb-selects {
	display: grid;
	gap: 12px;
	margin-bottom: 18px;
}
.dxb-selects {
	label {
		font-size: 11px;
		color: var(--muted);
	}
	select {
		display: block;
		width: 100%;
		padding: 8px;
		margin-top: 6px;
		min-width: 0;
		background: #121310;
	}
}
.dxb-arrival-row {
	display: flex;
	justify-content: space-between;
	border-bottom: 1px solid var(--line);
	padding: 9px 0;
	font-size: 13px;
	gap: 15px;
	strong {
		font-weight: 400;
		color: #ebcd95;
		white-space: nowrap;
	}
}
.dxb-route-story {
	display: block;
	padding: 12px 0;
	border-bottom: 1px solid var(--line);
	font-size: 14px;
	small {
		display: block;
		color: var(--muted);
		font-size: 12px;
	}
}
.dxb-route-photos {
	display: flex;
	gap: 10px;
	flex-wrap: wrap;
}
.dxb-route-photos {
	button {
		background: none;
		padding: 0;
		border: 1px solid var(--line);
	}
	img {
		width: 100px;
		height: 80px;
		object-fit: cover;
	}
}
.dxb-sr {
	position: absolute !important;
	width: 1px;
	height: 1px;
	padding: 0;
	margin: -1px;
	overflow: hidden;
	clip: rect(0, 0, 0, 0);
	white-space: nowrap;
	border: 0;
}
.dxb {
	dialog {
		width: min(1000px, 94vw);
		max-height: 92vh;
		overflow: auto;
		& > img {
			display: block;
			width: 100%;
			max-height: 61vh;
			object-fit: contain;
			background: #050605;
		}
	}
}
.dxb-close {
	position: absolute;
	top: 12px;
	right: 12px;
	width: 42px;
	height: 42px;
	background: #080807d9;
	border: 1px solid #a38c5f;
	color: white;
	font-size: 28px;
	z-index: 2;
}
.dxb-lightbox-nav {
	display: flex;
	align-items: center;
	justify-content: space-between;
	border-top: 1px solid var(--line);
	padding-top: 16px;
	margin-top: 20px;
	font-size: 12px;
	button {
		background: none;
		color: var(--gold);
		border: 0;
		padding: 8px;
	}
}
.dxb-tab-panel a:hover,
.dxb-resource:hover h3,
.dxb-section-heading a:hover {
	color: #ebcd95;
}
.dxb-lightbox-open {
	overflow: hidden;
}
.dxb-page #footer {
	margin-top: 0;
}
.dxb-journey-list {
	grid-template-columns: 1fr;
}
.dxb-journey-list {
	a {
		border-right: 0;
		border-bottom: 1px solid var(--line);
		&:last-child {
			border-bottom: 0;
		}
	}
}
.dxb-gallery-toolbar {
	align-items: flex-start;
	flex-direction: column;
}
@include respond-from(1001px) {
	.dxb-journey-list {
		grid-template-columns: repeat(3, 1fr);

		a {
			border-right: 1px solid var(--line);

			border-bottom: 0;
		}
	}

	.dxb-gallery-toolbar {
		align-items: center;

		flex-direction: row;
	}
}
.dxb-wrap {
	width: calc(100% - 36px);
}
.dxb-hero {
	padding-top: 135px;
}
.dxb h1 {
	font-size: clamp(32px, 7.4vw, 48px);
}
.dxb-intro {
	font-size: 15px;
	max-width: 300px;
}
.dxb-nav {
	gap: 23px;
	margin-top: 26px;
	a {
		transition:
			color 0.3s ease,
			background-color 0.3s ease,
			border-color 0.3s ease;
		font-size: 12px;
	}
}
.dxb-hero-media {
	height: 530px;
	img {
		object-position: 62% center;
	}
}
.dxb-explorer {
	grid-template-columns: 1fr;
	margin-top: 23px;
}
.dxb-explorer-main {
	padding: 25px 22px;
	h2 {
		font-size: 29px;
	}
}
.dxb-explorer-aside {
	border-left: 0;
	border-top: 1px solid var(--line);
	min-height: 310px;
}
.dxb-explorer-aside {
	> div {
		padding: 24px;
		pointer-events: none;
		background: linear-gradient(#080807d9, transparent);
	}
	h2 {
		font-size: 28px;
	}
	figure {
		inset: 0;
		&:after {
			background: linear-gradient(#08080780, transparent 50%, #080807);
		}
	}
	figcaption {
		left: 24px;
		font-size: 10px;
	}
}
.dxb-search {
	gap: 7px;
	input {
		font-size: 16px;
		width: calc(100% - 98px);
	}
}
.dxb-button {
	padding: 10px 13px;
	gap: 10px;
}
.dxb-tabs {
	gap: 19px;
	button {
		font-size: 11px;
	}
}
.dxb-section {
	margin-top: 45px;
}
.dxb-section-heading {
	align-items: flex-start;
	flex-wrap: wrap;
	gap: 10px;
}
.dxb-diary {
	grid-template-columns: 1fr;
}
.dxb-diary-photo {
	min-height: 310px;
	& > div {
		padding: 24px;
	}
}
.dxb-diary-notes {
	border-left: 0;
	border-top: 1px solid var(--line);
	padding: 26px;
	ol {
		margin-left: 33%;
	}
}
.dxb-gallery {
	grid-template-columns: 1fr;
	gap: 18px;
}
.dxb-gallery-toolbar {
	input {
		width: 100%;
		font-size: 16px;
	}
	& {
		gap: 14px;
	}
}
.dxb-photo-card > img {
	aspect-ratio: 1.5;
}
.dxb-editorial {
	grid-template-columns: 1fr;
	margin-top: 45px;
}
.dxb-editorial {
	> div {
		padding: 27px 0;
	}
	> aside {
		padding: 27px 0;
		border-left: 0;
		border-top: 1px solid var(--line);
	}
}
.dxb-signoff {
	flex-wrap: wrap;
	gap: 12px;
	font-size: 11px;
	a {
		margin-left: 0;
		width: 100%;
	}
}
.dxb-selects {
	grid-template-columns: 1fr;
	select {
		font-size: 16px;
	}
}
.dxb-lightbox-info {
	padding: 20px;
	h2 {
		font-size: 24px;
	}
}
@include respond-from(701px) {
	.dxb-wrap {
		width: 90%;
	}

	.dxb-hero {
		padding-top: 170px;
