	.dxb-schedule-state {
		display: grid;
		gap: 8px;
		border: 1px solid var(--line);
		background: linear-gradient(120deg, #d5ad6312, transparent);
		padding: 24px;
		margin: 18px 0;
	}
	.dxb-schedule-label {
		font-size: 10px;
		letter-spacing: 0.15em;
		color: var(--gold);
	}
	.dxb-schedule-state {
		strong {
			font-size: 18px;
			font-weight: 400;
			line-height: 24px;
		}
		p {
			font-size: 13px;
			line-height: 20px;
