/* Route explorer refinements. */
.dxb {
	.dxb-recent {
		flex-wrap: nowrap;
		overflow-x: auto;
		padding-bottom: 6px;
		button {
			display: inline-flex;
			align-items: center;
			justify-content: center;
			flex-shrink: 0;
		}
	}
}
body {
	.dxb {
		#dxb-route-input[data-spacing="tight"] {
			letter-spacing: -1px;
		}
		.dxb-recent [data-spacing="tight"] {
			letter-spacing: 0;
		}
		#dxb-route-input[data-spacing="normal"],
		.dxb-recent [data-spacing="normal"] {
			letter-spacing: 0;
		}
	}
}
.dxb {
	.dxb-tracking-breakdown {
		display: contents;
	}
	.dxb-deck-progress {
		flex: 0 0 100%;
	}
	button.dxb-deck-total {
		cursor: pointer;
		transition:
			border-color 0.25s ease,
			background-color 0.25s ease;
		&:hover {
			border-color: var(--gold);
			background: #d5ad631a;
		}
	}
	.dxb-arrival-card {
		&:not(.has-details) {
			padding: 12px 18px;
			margin-bottom: 10px;
		}
		&:not(.has-details) {
			.dxb-arrival-meta {
				margin: 8px 0 0;
			}
			.dxb-arrival-row {
				min-height: 0;
				padding: 0;
			}
		}
	}
	.dxb-visually-hidden {
		position: absolute;
		width: 1px;
		height: 1px;
		overflow: hidden;
		clip-path: inset(50%);
		white-space: nowrap;
	}
	.dxb-fleet-modal {
		max-height: 80vh;
		color: #f5f3ed;
		background: #10110e;
		overflow-y: auto;
		&::backdrop {
			background: #000b;
			backdrop-filter: blur(5px);
		}
