// DX Business HQ
body.dxcp-page .dxcp-shell.dxhq-shell {
	--dxhq-accent: var(--dxcp-link);
	--dxhq-tint: color-mix(in srgb, var(--dxcp-soft), #746c9e 12%);

	.dxcp-sidebar {
		animation: none;
		color-scheme: dark;
		color: #f4f0e8;
		background: #141414;
		border-color: #292722;
		--dxcp-muted: #c3c0b7;
		--dxcp-ink: #f4f0e8;
		--dxcp-soft: #24221e;
		--dxcp-selected: #312b20;
		--dxcp-selected-ink: #f7dea7;
		--dxcp-gold: #e0bc70;
		--dxcp-link: #e0bc70;

		nav {
			--workspace-nav-text: #c3c0b7;
			--workspace-nav-hover-text: #f4f0e8;
			grid-template-columns: 1fr;
			overflow-y: auto;
			overscroll-behavior: contain;
			a.dxcp-nav-link {
				color: var(--dxcp-ink);
				min-height: 36px;
				animation: none;
			}
		}
		a.dxcp-nav-link svg {
			flex: 0 0 17px;
		}
		.dxcp-brand {
			padding-bottom: 21px;
			color: var(--dxcp-ink);
			small {
				max-width: 72px;
			}
		}
		.dxcp-sidebar__bottom {
			flex: 0 0 auto;
			border-top: 1px solid #32302a;
			margin-top: auto;
			padding-top: 8px;
		}
	}

	.dxhq-nav-group {
		summary {
			display: flex;
			justify-content: space-between;
			align-items: center;
			cursor: pointer;
			color: var(--dxcp-muted);
			font-size: 11px;
			letter-spacing: 0.08em;
			text-transform: uppercase;
			padding: 7px 10px;
			list-style: none;

			&::-webkit-details-marker {
				display: none;
			}
			&::after {
				content: "";
				inline-size: 7px;
				block-size: 7px;
				border: solid currentColor;
				border-width: 0 1px 1px 0;
				transform: rotate(-45deg);
			}
		}

		&[open] summary::after {
			transform: translateY(-2px) rotate(45deg);
		}
		.dxcp-nav-link[aria-current] {
			box-shadow: inset 3px 0 var(--dxcp-gold);
		}
		:is(summary, a):focus-visible {
			outline: 2px solid var(--dxcp-gold);
			outline-offset: -2px;
		}
	}

	.dxcp-content {
		padding-top: clamp(22px, 4vw, 46px);
	}
	.dxhq-module-heading h1 {
		font-size: clamp(2rem, 3vw, 3rem);
	}

	.dxhq-overview-heading {
		display: flex;
		flex-wrap: wrap;
		justify-content: space-between;
		align-items: end;
		gap: 10px 20px;
		margin-bottom: 22px;

		h1 {
			font-size: clamp(2.3rem, 4.2vw, 4rem);
			line-height: 1;
			margin: 0 0 8px;
		}
		p {
			margin: 0;
			color: var(--dxcp-muted);
		}
		time {
			font-size: 0.8rem;
			color: var(--dxcp-muted);
		}
	}

	.dxhq-kpis {
		display: grid;
		grid-template-columns: repeat(auto-fit, minmax(min(100%, 160px), 1fr));
		gap: 10px;
		margin-bottom: 18px;
	}

	.dxhq-kpi {
		display: flex;
		flex-direction: column;
		align-items: start;
		gap: 6px;
		min-width: 0;
		padding: clamp(12px, 1.6vw, 20px);
		background: var(--dxcp-surface);
		border: 1px solid var(--dxcp-line);
		color: var(--dxcp-ink);
		line-height: 1.3;
		text-decoration: none;
		transition:
			background-color 0.2s ease,
			border-color 0.2s ease;

		> span:not(.dxhq-kpi__icon) {
			font-size: 0.8rem;
		}
		strong {
			color: var(--dxcp-ink);
			font-size: clamp(1.15rem, 1.65vw, 1.6rem);
			line-height: 1.08;
			font-variant-numeric: tabular-nums;
			overflow-wrap: anywhere;
		}
		small {
			color: var(--dxcp-muted);
			font-size: 0.7rem;
		}
		&:is(:hover, :focus-visible) {
			background: var(--dxhq-tint);
			border-color: var(--dxhq-accent);
		}
	}

	.dxhq-kpi__icon {
		display: grid;
		place-items: center;
		width: 30px;
		height: 30px;
		margin-bottom: 3px;
		background: var(--dxcp-selected);
		color: var(--dxcp-selected-ink);

		svg {
			width: 17px;
			height: 17px;
		}
	}

	.dxhq-grid {
		display: grid;
		grid-template-columns: minmax(0, 1fr);
		gap: 14px;
		@include media-breakpoint-up(md) {
			grid-template-columns: minmax(0, 1.5fr) minmax(0, 1fr);
		}
	}

	.dxhq-panel {
		min-width: 0;
		padding: clamp(16px, 2.2vw, 28px);
		margin-bottom: 14px;
		border: 1px solid var(--dxcp-line);

		h2 {
			font-size: 1.25rem;
			margin: 0 0 12px;
		}
		h3 {
			font-size: 0.95rem;
			margin: 0 0 12px;
		}
		p:last-child {
			margin-bottom: 0;
		}
	}

	.dxhq-attention {
		align-items: center;
		padding-inline: 8px;
		.dxhq-attention__action {
			display: flex;
			align-items: center;
			gap: 5px;
			color: var(--dxhq-accent);
			font-size: 0.73rem;
			text-align: end;
		}
		svg {
			flex: 0 0 13px;
			width: 13px;
			height: 13px;
		}
	}

	.dxhq-quick-actions {
		display: grid;
		grid-template-columns: repeat(auto-fit, minmax(min(100%, 140px), 1fr));
		gap: 6px;
		a {
			display: flex;
			align-items: center;
			gap: 8px;
			padding: 9px 10px;
			min-height: 44px;
			border: 1px solid var(--dxcp-line);
			color: var(--dxcp-ink);
			font-size: 0.78rem;
			text-decoration: none;
			transition:
				background-color 0.2s ease,
				border-color 0.2s ease;

			&:is(:hover, :focus-visible) {
				background: var(--dxhq-tint);
				border-color: var(--dxhq-accent);
			}
		}
		svg {
			width: 15px;
			height: 15px;
			flex: 0 0 15px;
			color: var(--dxhq-accent);
		}
	}

	.dxhq-analytics-heading {
		display: flex;
		align-items: baseline;
		flex-wrap: wrap;
		justify-content: space-between;
		gap: 4px 10px;
	}

	.dxhq-date-range {
		display: flex;
		align-items: end;
		flex-wrap: wrap;
		gap: 8px;
		margin: 0 0 16px;

		.dxcp-field {
			flex: 1 1 125px;
			max-width: 160px;
			min-width: 0;
		}
		.dxcp-text-link {
			align-self: center;
		}
	}

	.dxhq-analytics-grid {
		display: grid;
		grid-template-columns: repeat(auto-fit, minmax(min(100%, 215px), 1fr));
		align-items: start;
		gap: 12px;

		> div {
			min-width: 0;
			background: var(--dxcp-canvas);
			border: 1px solid var(--dxcp-line);
			padding: 12px;
		}
		.dxcp-list-row {
			padding-block: 6px;
			min-height: 0;
			font-size: 0.78rem;
		}
	}

	.dxhq-chart-row {
		display: grid;
		gap: 5px;
		margin-bottom: 8px;

		div {
			display: flex;
			flex-wrap: wrap;
			justify-content: space-between;
			gap: 3px 8px;
			font-size: 0.75rem;
		}
		meter {
			width: 100%;
			height: 6px;
			background: var(--dxcp-line);
			&::-webkit-meter-bar {
				background: var(--dxcp-line);
				border: 0;
			}
			&::-webkit-meter-optimum-value {
				background: var(--dxhq-accent);
			}
			&::-moz-meter-bar {
				background: var(--dxhq-accent);
			}
		}
	}

	@media (prefers-reduced-motion: reduce) {
		:is(.dxhq-kpi, .dxhq-quick-actions a) {
			transition: none;
		}
	}
}

body.dxbus-page .dxbus-app .dxbus-stats {
	z-index: 4;
	margin-top: 0;
}

.dxbus-route-glyphs {
	vertical-align: baseline;

	sup {
		align-self: start;
	}
}

body.dxgym-page #dxgym-app .dxgym-map .dxgym-marker-tooltip {
	opacity: 0 !important;
	visibility: hidden;
	transition:
		opacity 0.18s ease,
		visibility 0s 0.18s;

	&.is-visible {
		opacity: 1 !important;
		visibility: visible;
		transition-delay: 0s;
	}
}

body.is-frontend.single-project #main .chapter-selector .dx-project-rail-title {
	margin: 0 0 12px;
	color: #fff7e8;
	font:
		400 clamp(16px, 1.6vw, 26px) / 1.12 "Space Grotesk",
		sans-serif;
	opacity: 0;
	transform: translateY(6px);
	transition:
		opacity 0.28s ease,
		transform 0.34s ease;
	pointer-events: none;

	&.is-visible {
		opacity: 1;
		transform: none;
	}

	small {
		display: block;
		margin-bottom: 4px;
		color: #e1be7b;
		font-size: 0.55em;
		text-transform: uppercase;
	}
}

body.home #main {
	.dx-mobile-services.is-cinema > .accordion-item {
		border: 0 !important;
	}
	.dx-services-swipe-hint {
		color: #e1be7b;
		font:
			600 clamp(20px, 5vw, 30px) / 1.15 Outfit,
			sans-serif;
		text-align: center;
	}
}

@media (prefers-reduced-motion: reduce) {
	body.dxgym-page #dxgym-app .dxgym-map .dxgym-marker-tooltip,
	body.is-frontend.single-project
		#main
		.chapter-selector
		.dx-project-rail-title {
		transition: none;
		transform: none;
	}
}

.cv-industry {
	padding-block: 2rem;
	h2 {
		font-size: clamp(1.35rem, 2.5vw, 2rem);
	}
	ul {
		display: flex;
		flex-wrap: wrap;
		gap: 0.75rem;
		padding: 0;
		margin: 0;
		list-style: none;
	}
	a[aria-current] {
		background: var(--cv-gold, #d9b974);
		color: #111;
	}
}

.dx-rail-name {
	display: block;
	max-inline-size: 100%;
	overflow: hidden;
	white-space: nowrap;
	> span {
		display: inline-block;
	}
}
@media (prefers-reduced-motion: reduce) {
	.dx-rail-name {
		white-space: normal;
		overflow-wrap: anywhere;
	}
}

.cv-experience .cv-industry {
	padding: clamp(1.25rem, 4vw, 3rem);
	margin-block: clamp(1.5rem, 4vw, 3rem);
	border-block: 1px solid #d9b97455;
	background: linear-gradient(105deg, #d9b97410, transparent 65%);
	ul {
		display: grid;
		grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr));
		gap: 0.65rem;
	}
	.cv-button {
		display: flex;
		min-height: 54px;
		justify-content: space-between;
		align-items: center;
		gap: 0.75rem;
		text-align: left;
		padding: 0.85rem 1rem;
		&::after {
			content: "↗";
			color: #d9b974;
		}
	}
	.cv-button[aria-current]::after {
		content: "✓";
		color: inherit;
	}
	&[aria-busy] ul {
		opacity: 0.68;
	}
}

body.is-frontend #main .calculator-experience {
	min-height: 100vh;
	.calculator-session {
		display: flex;
		flex-wrap: wrap;
		align-items: center;
		gap: 0.45rem 0.8rem;
		font-size: 0.78rem;
		:is(button, select) {
			min-height: 44px;
			max-width: 100%;
			color: #efe6d4;
			background: #171614;
			border: 1px solid #d7ad5750;
			padding-inline: 0.65rem;
		}
	}
	[data-dock-progress] {
		display: none;
	}
	.calculator-sheet {
		margin: auto;
		width: min(100%, 40rem);
		max-height: 80dvh;
		overflow: auto;
		overscroll-behavior: contain;
		padding: 1.25rem;
		border: 1px solid #d7ad5766;
		background: #151412;
		color: #f5efe3;
		&::backdrop {
			background: #000a;
		}
		&[open] {
			animation: calculator-sheet-in 0.2s ease-out;
		}
		&__header {
			display: flex;
			justify-content: space-between;
			align-items: start;
			gap: 0.75rem;
		}
		h2 {
			font-size: 1.35rem;
		}
		button {
			min-height: 44px;
			padding-inline: 0.85rem;
			background: none;
			color: #f0cf87;
			border: 1px solid #d7ad5766;
		}
		.summary-breakdown {
			list-style: none;
			padding: 0;
			li {
				display: flex;
				justify-content: space-between;
				gap: 0.75rem;
				padding: 0.5rem 0;
				border-bottom: 1px solid #ffffff20;
			}
		}
	}
	.calculator-step .step-title {
		scroll-margin-top: 110px;
	}
	:focus-visible {
		outline: 2px solid #f0cf87;
		outline-offset: 3px;
	}
}

// Keep native radio semantics while drawing one aligned indicator.
body.page-pricing-calculator .pricing-calculator {
	.options-group input[type="radio"] { position: absolute !important; width: 1px !important; height: 1px !important; padding: 0 !important; margin: -1px !important; overflow: hidden !important; clip-path: inset(50%) !important; opacity: 0 !important; }
	.custom-radio { position: relative !important; flex-shrink: 0; }
	.custom-radio::after { position: absolute !important; left: 50% !important; top: 50% !important; right: auto !important; bottom: auto !important; transform: translate(-50%, -50%) !important; width: 7px !important; height: 7px !important; border-radius: 50%; position: absolute !important; top: 50% !important; left: 50% !important; transform: translate(-50%, -50%) scale(0.55) !important; background: #e1bd70 !important; opacity: 0; }
	.custom-radio { position: relative !important; transition: border-color 180ms ease, background-color 180ms ease, box-shadow 180ms ease, opacity 180ms ease; }
	.options-group label { transition: background-color 180ms ease, border-color 180ms ease, box-shadow 180ms ease, opacity 180ms ease; }
	.custom-radio::after { transition: opacity 180ms ease, transform 180ms ease, background-color 180ms ease; }
	input[type="radio"]:disabled + .custom-radio { opacity: 0.4; }
	.options-group label:has(input[type="radio"]:disabled) { opacity: 0.5; }
	.options-group label:hover .custom-radio, input[type="radio"]:focus-visible + .custom-radio { border-color: #efd297; box-shadow: 0 0 0 3px #d7ad5722; }
	@media (prefers-reduced-motion: reduce) { .custom-radio, .custom-radio::after, .options-group label { transition: none !important; } }
	.category-card .custom-radio { position: relative !important; align-self: center; justify-self: center; margin: 0 !important; inset: auto !important; }
	input[type="radio"]:checked + .custom-radio::after { opacity: 1; transform: translate(-50%, -50%) scale(1) !important; }
	input[type="radio"]:checked + .custom-radio { border-color: #e1bd70; background: transparent; box-shadow: none; }
	.options-group label:has(input:focus-visible) { outline: 2px solid #efd297; outline-offset: 3px; }
	.calculator-progress { padding-bottom: 0.85rem; }
	:is(.price, .dx-photo-price, .service-option__price) { font-variant-numeric: tabular-nums; }
	.nav-estimate :is(button, .price, span) { color: #efd297 !important; }
	.progress-fill { transition: width 280ms ease, background 280ms ease, box-shadow 280ms ease; }
	.calculator-segments { gap: 0 !important; }
	.calculator-segments span { min-width: 0; margin-inline-end: 0.3rem; }
	.calculator-segments span.is-unused { flex: 0 1 0% !important; opacity: 0; margin-inline-end: 0; outline: 0 !important; box-shadow: none !important; }

	.calculator-segments span { min-width: 0; margin-inline-end: 0.3rem; }
	.calculator-segments span.is-unused { flex-grow: 0 !important; flex-basis: 0 !important; width: 0; margin-inline-end: 0; opacity: 0; outline: 0 !important; }
	.calculator-segments span { min-width: 0; margin-right: 0.3rem; }
	.calculator-segments span.is-unused { flex: 0 1 0 !important; opacity: 0; margin-right: 0; outline: 0; }
	.calculator-segments span { transition: flex-grow 280ms ease, opacity 220ms ease, margin 280ms ease, background 280ms ease, box-shadow 280ms ease, outline-color 280ms ease; }
	&.is-final-step { .progress-fill, .calculator-segments span { background: #e5e4e2 !important; box-shadow: 0 0 8px #e5e4e288, 0 0 18px #e5e4e244; outline-color: #e5e4e2 !important; } }
	@include media-breakpoint-down(xl) {
		.calculator-nav {
			grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) !important;
			gap: 0.4rem 0.65rem;
			[data-dock-progress] { grid-column: 1 / -1 !important; justify-self: center; text-align: center; text-transform: uppercase; letter-spacing: 0.12em; font-size: 0.65rem !important; font-weight: 600; }
			.nav-estimate { grid-row: 2 !important; grid-column: 1 / -1 !important; justify-self: center !important; }
			.nav-estimate button { height: auto; min-height: 30px; translate: 0 0.5rem; }
			> :is(.prev-step, .next-step) { grid-row: 3 !important; border-radius: 0; text-transform: uppercase; letter-spacing: 0.12em; font-size: 0.7rem !important; font-weight: 600; transition: background 180ms ease, color 180ms ease, opacity 180ms ease, translate 180ms ease; }
			> .prev-step { background: transparent !important; color: #e1bd70 !important; border: 1px solid #d7ad57 !important; }
			> .next-step { border: 1px solid #d7ad57 !important; }
			> .prev-step.is-hidden + .next-step { grid-column: 1 / -1 !important; }
			> .next-step::after { content: '↗'; display: inline-block; margin-left: 0.75rem; transition: translate 180ms ease; }
			> .next-step:hover::after { translate: 2px -2px; }
			> .prev-step::before { content: '←'; margin-right: 0.5rem; }
			> :is(.prev-step, .next-step):hover { background: #efd297 !important; color: #101110 !important; }
		}
		.calculator-session { flex-wrap: nowrap !important; gap: 0.4rem; margin-bottom: 0.75rem; }
		.calculator-session select { flex: 1 1 0; width: 0; min-width: 0; }
		.calculator-session [data-session-status] { @include visually-hidden; }
		.calculator-session :is(button, .dx-basket-command-style) { flex: 0 0 auto; white-space: nowrap; font-size: 0.7rem !important; padding-inline: 0.45rem !important; }
		.calculator-session .dx-basket-command-style svg { width: 1rem; height: 1rem; }
	}
	@media (prefers-reduced-motion: reduce) { .progress-fill, .calculator-segments span { transition: none; } }
}

body.page-pricing-calculator .pricing-calculator {
	.service-option__information[hidden] { display: none !important; }
	.service-option__details-link {
		display: inline-flex; align-items: center; gap: 0.4rem;
		width: fit-content; min-height: 32px; margin-top: 0.3rem;
		font-size: 0.7rem; font-weight: 500; line-height: 1.3;
		letter-spacing: 0.1em; text-transform: uppercase;
		color: #e1bd70; text-decoration: none;
		border: 0; background: transparent;
		span { transition: translate 180ms ease; }
		&:hover span { translate: 2px -2px; }
