// Calculator dialog family and shared progress motion.
body.page-pricing-calculator {
	:is(.calculator-sheet, .calculator-restart-dialog, .dx-estimate-notice, .package-comparison, [data-calculator-restart-dialog]) {
		border: 0 !important;
		border-radius: 0.75rem 0.75rem 0 0;
		background: #111312 !important;
		color: #f5efe3;
		box-shadow: 0 -1rem 4rem #0005;
		padding: clamp(1.25rem, 4vw, 2rem);
		&::backdrop { background: #0009; backdrop-filter: blur(5px); transition: background 180ms, backdrop-filter 180ms; }
		&.is-closing::backdrop { background: #0000; backdrop-filter: blur(0); }
		@starting-style { &::backdrop { background: #0000; backdrop-filter: blur(0); } }
		:is(header, .calculator-sheet__header) { display: flex; align-items: flex-start; gap: 1rem; margin-bottom: 1.75rem; }
		h2 { font-size: clamp(1.25rem, 3vw, 1.65rem); line-height: 1.3; font-weight: 600; letter-spacing: -0.025em; margin: 0; }
		button { min-height: 44px; padding: 0.6rem 1rem; border: 0; border-radius: 0.25rem; background: #d7ad571a; color: #efd297; font-size: 0.9rem; }
		:is(header, .calculator-sheet__header) > button { margin-left: auto; flex-shrink: 0; }
		ul:not(.summary-breakdown) { list-style: none; padding: 0; display: grid; gap: 1rem; margin-block: 0; }
		li { line-height: 1.65; }
		.service-detail-list { gap: 0.65rem !important; }
		.service-detail-list li { margin-block: 0 !important; }
		ul:not(.summary-breakdown) li { padding-left: 1rem; position: relative; font-size: 0.95rem; }
		ul:not(.summary-breakdown) li::before { content: ''; position: absolute; left: 0; top: 0.65em; width: 4px; height: 4px; border-radius: 50%; background: #d7ad57; }
	}
		.calculator-sheet .calculator-dialog-close {
			display: grid; place-items: center; flex: 0 0 44px;
			width: 44px; height: 44px; min-height: 44px;
