// A generous, feathered window onto the bus film between route search and diary.
body.is-frontend #main .dxb .dxb-video-interlude {
 position: relative;
 width: 100vw;
 max-width: none;
 margin-inline: calc(50% - 50vw);
 height: clamp(460px, 70svh, 900px);
 margin-block: clamp(48px, 7vw, 120px);
 overflow: hidden;
 pointer-events: none;
 isolation: isolate;
 mask-image: linear-gradient(to bottom, transparent, #000 25%, #000 72%, transparent);
 > img, > video {
  position: absolute; inset: 0;
  width: 100%; height: 100%; object-fit: cover;
  object-position: center;
 }
 > img { opacity: .62; }
 > video {
  opacity: 0;
  transition: opacity 1.6s ease;
  &.is-ready { opacity: .85; }
 }
 &::after { content: ''; position: absolute; inset: 0; background: linear-gradient(90deg, #08090755, transparent 35%, #08090722); }
 @media (max-width: 767px) { height: clamp(360px, 60svh, 580px); margin-block: 48px; }
 @media (prefers-reduced-motion: reduce) { > video { transition: none; } }
}

// Keep the editorial image blend while smoothly zooming within the article bounds.
body.is-frontend #main .dxb-editorial .dxb-article {
 overflow: hidden;
 > img {
  transform: scale(1);
  transform-origin: right center;
  transition: transform 950ms cubic-bezier(.22, 1, .36, 1);
 }
 @media (hover: hover) and (pointer: fine) {
  &:hover > img { transform: scale(1.065); }
 }
 &:focus-visible > img { transform: scale(1.065); }
 @media (prefers-reduced-motion: reduce) {
  > img { transition: none; }
  &:hover > img, &:focus-visible > img { transform: none; }
 }
}

// The diary moves over a slower, taller film window.
body.is-frontend #main .dxb .dxb-video-interlude {
 height: 100vh;
 min-height: 80vh;
 margin-bottom: 0;
 mask-image: linear-gradient(to bottom, transparent, #000 18%, #000 76%, transparent);
 > img, > video {
  top: -15%; bottom: auto; height: 130%;
  transform: translateY(var(--bus-film-offset, 0px));
 }
 > img { transition: opacity 1.6s ease; }
 > video.is-ready { opacity: 1; }
 &.has-ready-video > img { opacity: 0; }
 + #bus-diary {
  position: relative;
  z-index: 2;
  margin-top: clamp(-220px, -18vh, -100px);
  padding-top: 0;
  background: transparent;
 }
 @media (max-width: 767px) {
  height: 90vh;
  min-height: 80vh;
  + #bus-diary { margin-top: -12vh; }
 }
 @media (prefers-reduced-motion: reduce) {
  > img, > video { transform: none; }
  > img { transition: none; }
 }
}

