 .service-choice-checkbox{display:block!important;position:relative!important;width:26px!important;height:26px!important;flex:0 0 26px!important;justify-self:end;align-self:center;border:1px solid #c7c8bdaa!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;margin-right:0!important;transition:background-color 220ms ease,border-color 220ms ease,box-shadow 220ms ease!important;
  &::after{content:''!important;position:absolute!important;left:8px!important;top:4px!important;width:8px!important;height:14px!important;inset:auto!important;left:8px!important;top:4px!important;border:solid #111a16!important;border-width:0 2px 2px 0!important;border-radius:0!important;background:transparent!important;opacity:0!important;transform:rotate(45deg) scale(.65)!important;transition:opacity 200ms ease,transform 220ms cubic-bezier(.22,1,.36,1)!important;}
 }
 input[type=checkbox]:checked~.service-choice-checkbox{background:#d6ae4f!important;border-color:#edca77!important;
  &::after{opacity:1!important;transform:rotate(45deg) scale(1)!important;}
 }
 label:hover .service-choice-checkbox{border-color:#f0d28d!important;box-shadow:0 0 0 3px #d6ae4f18!important;}
 label:has(input:focus-visible){outline:2px solid #efd297;outline-offset:3px;}
 label:has(input:disabled){opacity:.45!important;}
 @media(prefers-reduced-motion:reduce){.service-option>label,.service-choice-checkbox,.service-choice-checkbox::after{transition:none!important;}}
}
body.is-frontend #main .pricing-calculator .options-group--services .service-choice-checkbox{margin-left:12px!important;}
@media(max-width:1199.98px){
 body.is-frontend #main .pricing-calculator .options-group--services .service-option>label{grid-template-columns:minmax(0,1fr) auto 26px!important;column-gap:12px!important;}
 body.is-frontend #main .pricing-calculator .options-group--services .service-choice-checkbox{margin-left:0!important;grid-column:3;grid-row:1;}
 body.is-frontend #main .pricing-calculator .options-group--services .service-option__copy{grid-column:1;grid-row:1;}
 body.is-frontend #main .pricing-calculator .options-group--services .service-option__price{grid-column:2;grid-row:1;}
}

