body.is-frontend #main .pricing-calculator .options-group--services {
 display:grid!important;grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:18px!important;
 border:0!important;background:transparent!important;overflow:visible!important;max-height:none!important;
 .service-option{display:flex!important;min-width:0!important;border:0!important;margin:0!important;}
 .service-option>label{
  position:relative!important;isolation:isolate;overflow:hidden!important;display:flex!important;flex-direction:column!important;align-items:flex-start!important;
  width:100%!important;min-height:330px!important;height:100%!important;padding:76px 24px 26px!important;margin:0!important;
  border:1px solid #a28d514f!important;border-radius:0!important;background:#0c1415!important;box-shadow:none!important;cursor:pointer;
  transition:border-color .28s ease,box-shadow .28s ease,background-color .28s ease!important;
  &::before{content:'';position:absolute;inset:0;z-index:-1;pointer-events:none;background:linear-gradient(180deg,#07101433 0%,#071014a8 35%,#081113ed 76%,#081113 100%);transition:background .3s ease;}
  &:hover{border-color:#dab66a!important;box-shadow:0 12px 30px #0003!important;}
  &:has(input:checked){border-color:#e5c276!important;box-shadow:inset 0 0 0 1px #d6ae4f66!important;background:#18201a!important;}
  &:has(input:checked)::before{background:linear-gradient(180deg,#48361835 0%,#171c16bd 35%,#151b15f5 80%,#151b15 100%);}
 }
 .service-option__image{display:block!important;position:absolute!important;inset:0!important;width:100%!important;height:100%!important;object-fit:cover!important;z-index:-2!important;margin:0!important;opacity:.8!important;mask-image:linear-gradient(180deg,#000 0%,#000a 55%,transparent 100%);transform:scale(1);transition:transform .8s cubic-bezier(.22,1,.36,1),opacity .35s ease!important;}
 .service-option>label:hover .service-option__image{transform:scale(1.045);opacity:1!important;}
 .service-option__number{display:block!important;position:absolute;top:25px;left:24px;color:#f0ce83!important;font:500 11px/1 'Outfit',sans-serif;letter-spacing:.15em;}
 .service-choice-checkbox{position:absolute!important;top:22px!important;right:22px!important;margin:0!important;grid-area:auto!important;z-index:2;background:#071014a8!important;}
 input:checked~.service-choice-checkbox{background:#d6ae4f!important;}
 .service-option__copy{display:flex!important;flex-direction:column!important;align-items:flex-start!important;gap:13px!important;align-self:stretch!important;flex:1!important;min-width:0!important;}
 .service-option__copy strong{font:500 clamp(20px,1.6vw,25px)/1.18 'Space Grotesk',sans-serif!important;letter-spacing:-.035em;color:#f5f1e5!important;}
 .service-option__copy>span{display:block!important;color:#d8d9d1!important;font:400 14px/1.65 'Outfit',sans-serif!important;}
 .service-option__details-link{margin-top:auto!important;padding:14px 0 0!important;color:#f0cb77!important;font-size:11px!important;letter-spacing:.08em;position:relative;z-index:3;}
 .service-option__price{display:block!important;align-self:flex-start!important;text-align:left!important;margin-top:23px!important;color:#f0c66b!important;font-size:25px!important;}
 .service-option__price small{color:#ded8c6!important;}
 @media(max-width:600px){grid-template-columns:1fr!important;.service-option>label{min-height:290px!important;padding:72px 24px 24px!important;}}
 @media(prefers-reduced-motion:reduce){.service-option__image{transition:none!important;transform:none!important;}}
}
@media(max-width:1199.98px){
 body.page-pricing-calculator.is-frontend #main .pricing-calculator .options-group--services .service-option>label{
  display:flex!important;flex-direction:column!important;align-items:flex-start!important;padding:72px 24px 24px!important;min-height:310px!important;
  .service-option__copy{grid-area:auto!important;width:100%!important;flex:1!important;}
  .service-option__price{position:relative!important;inset:auto!important;grid-area:auto!important;margin:22px 0 0!important;align-self:flex-start!important;text-align:left!important;}
  .service-option__number{top:25px!important;left:24px!important;}
  .service-choice-checkbox{position:absolute!important;top:22px!important;right:22px!important;grid-area:auto!important;margin:0!important;}
 }
}

