// Shared editorial refinements — November 21.
body.is-frontend #main {
	.dx-pulse {
		.dx-pulse-feature,
		.dx-pulse-section {
			isolation: isolate;

			&::before {
				content: '';
				position: absolute;
				inset: -90px -8vw;
				z-index: -1;
				pointer-events: none;
				background: radial-gradient(ellipse at 12% 45%, #643c553b, transparent 58%), radial-gradient(ellipse at 90% 65%, #2c59613b, transparent 58%);
			}
		}

		.dx-pulse-section {
			position: relative;
			margin-top: clamp(90px, 12vw, 190px);
		}

		.dx-pulse-feature-copy h2 {
			font-weight: 400;
			line-height: 1.08;
		}

		.dx-pulse-choice input[type="radio"] {
			min-height: 23px;
			max-height: 23px;
			height: 23px;
			width: 23px;
			padding: 0;
		}

		.dx-pulse-card h3 {
			font-size: clamp(23px, 2vw, 30px);
			font-weight: 400;
			line-height: 1.12;
		}

		.dx-pulse-hero h1 {
			max-width: 10ch;
		}

		.dx-pulse-hero-image {
			inset-block: -7% 0;
			will-change: transform;

			img {
				object-fit: contain;
				object-position: right center;
			}
		}
	}

	.dx-pulse[data-pulse-stats] {
		background: transparent;

		.dx-pulse-section::before,
		.dx-pulse-feature::before {
			content: none;
		}

		.dx-pulse-scenes {
			position: fixed;
			inset: 0;
			z-index: -1;
			width: 100%;
			height: 100svh;
			pointer-events: none;
			background: #080b0b;
		}

		.dx-pulse-scene {
			position: absolute;
			inset: 0;
			opacity: 0;
			background: radial-gradient(ellipse at 8% 45%, var(--pulse-scene-a), transparent 62%), radial-gradient(ellipse at 94% 65%, var(--pulse-scene-b), transparent 64%);
			transition: opacity .85s ease;

			&.is-active {
				opacity: 1;
			}
		}

		.dx-pulse-hero::after {
			inset: -150px 0;
			background: radial-gradient(ellipse at 12% 48%, #080b0be6 0%, #080b0b80 40%, transparent 74%);
			mask-image: linear-gradient(transparent, #000 24%, #000 70%, transparent);
			pointer-events: none;
		}

		.dx-pulse-hero-image {
			mask-image: linear-gradient(transparent, #000 18%, #000 72%, transparent);
			inset: -18% -12% -8% 24%;
			opacity: .65;

			@include media-breakpoint-up(md) {
				inset-inline-start: 34%;
				opacity: 1;
			}
		}
	}

	.dx-pulse {
		.dx-pulse-eyebrow {
			margin-bottom: clamp(18px, 2vw, 28px);

			+ :is(h1, h2, h3) {
				margin-top: 0;
			}
		}

		.dx-pulse-stats a {
			text-transform: none;
		}

		.dx-pulse-filter-feedback {
			grid-column: 1 / -1;
			font-size: 13px;
			color: #e4c785;
		}
	}

	.dx-pulse.dx-pulse-teaser {
		position: relative;
		left: 50%;
		width: 100vw;
		max-width: none;
		margin: 80px 0 0 -50vw;
		padding: clamp(70px, 8vw, 130px) 0;
		min-height: 90svh;
		border: 0;
		background: #080b0b;
		isolation: isolate;

		&::before {
			background: radial-gradient(ellipse at 20% 20%, #5f3a3f4d, transparent 55%), radial-gradient(ellipse at 90% 65%, #2a444c59, transparent 60%);
		}

		.dx-pulse-wrap {
			position: relative;
			z-index: 1;
			width: 88%;
		}

		.dx-pulse-feature {
			margin-top: 42px;
		}

		.dx-pulse-teaser-heading {
			max-width: 900px;

			h2 {
				font-size: clamp(44px, 7vw, 105px);
				line-height: 1.03;
				margin: 18px 0;
			}
		}

		.dx-pulse-teaser-invite {
			display: flex;
			align-items: center;
			justify-content: space-between;
			flex-wrap: wrap;
			gap: 20px;
			padding-top: 28px;

			p {
				max-width: 580px;
				font-size: 16px;
			}
		}

		.dx-pulse-teaser-art {
			position: absolute;
			inset: 0 0 auto 40%;
			height: 55%;
			z-index: -1;
			opacity: .3;
			mask-image: linear-gradient(#0007, transparent 95%);
			pointer-events: none;

			img {
				width: 100%;
				height: 100%;
				object-fit: contain;
				object-position: right top;
			}
		}
	}

	.portfolio-editorial .dx-project-poster > div > .dx-project-poster-action,
	.story-hero a.dx-read-study {
		font-family: Outfit, sans-serif;
		text-transform: uppercase;
		font-size: 13px;
		font-weight: 500;
		letter-spacing: .12em;
	}

	.dx-portfolio-hero > img {
		// The page-ready entrance owns this portrait; no second CSS animation.
		animation: none;
	}

	.dx-private-chapters-title {
		display: flex;
		align-items: center;
		gap: 12px;
		text-transform: uppercase;
	}

	.dx-private-title-lock {
		width: 25px;
		height: 25px;
		flex: 0 0 auto;
		color: #d7ad57;
	}

	// Use the same frame and type scale for both portfolio closing sections.
	.dx-editorial-contact,
	.dx-app-entry {
		padding: clamp(70px, 9vw, 140px) 8vw;

		h2 {
			font-family: "Space Grotesk", Outfit, sans-serif;
			font-size: clamp(58px, 9vw, 160px);
			font-weight: 400;
			letter-spacing: -.055em;
			line-height: 1.03;
			margin: 0 0 40px;
		}
	}

	.dx-app-entry {
		position: relative;
		isolation: isolate;
		box-shadow: none;
		clip-path: none;
		background: radial-gradient(ellipse at 82% 50%, #75513b59, transparent 62%), radial-gradient(ellipse at 55% 65%, #43364d45, transparent 60%), #101211;

		.dx-app-entry__inner {
			width: 100%;
			max-width: none;
			padding: 0;
			margin: 0;
			grid-template-columns: minmax(0, 1fr);
		}

		p {
			font: 400 18px/1.5 Outfit, sans-serif;
			max-width: 580px;
			margin-bottom: 30px;
		}

		.dx-app-teaser__art {
			justify-self: center;
			width: min(100%, 34rem);
		}

		@include media-breakpoint-up(lg) {
			.dx-app-entry__inner {
				grid-template-columns: 1.15fr 1fr;
			}

			.dx-app-teaser__art {
				justify-self: end;
			}
		}
	}
}

@include media-breakpoint-up(lg) {
	body.home.is-frontend #main .what-i-do .services-tabs {
		position: relative;
		isolation: isolate;
		padding-block: 70px;
		min-height: 740px;

		> .row {
			position: relative;
			z-index: 1;
			align-items: center;
		}

		.dx-service-scene {
			position: absolute;
			inset: -30px auto;
			left: 50%;
			width: 100vw;
			max-width: none;
			transform: translateX(-50%);
			z-index: -1;
			overflow: hidden;
			pointer-events: none;
			mask-image: linear-gradient(transparent, #000 18%, #000 82%, transparent);

			&::after {
				content: '';
				position: absolute;
				inset: 0;
				background: linear-gradient(90deg, #080b0bf0 5%, #080b0bad 40%, #080b0b99 80%), linear-gradient(0deg, #080b0b, transparent 35%);
			}
		}

		.dx-service-scene-layer {
			position: absolute;
			inset: 0;
			width: 100%;
			height: 100%;
			object-fit: cover;
			opacity: 0;
			transform: scale(1.045);
			transition: opacity 1.1s ease, transform 1.8s ease;

			&.is-active {
				opacity: .8;
				transform: scale(1);
			}
		}

		.tab-content {
			background: transparent;
			padding-left: clamp(25px, 5vw, 80px);
		}

		.tab-pane {
			position: relative;
			min-height: 570px;
			padding: 45px 0;
			background: transparent;

			> .service-image {
				display: none;
			}

			&.active {
				display: flex;
				flex-direction: column;
				align-items: flex-start;
				justify-content: center;
			}

			h3 {
				font-size: clamp(44px, 5vw, 82px);
				line-height: 1.05;
				max-width: 15ch;
				margin-bottom: 25px;
			}

			p {
				font-size: 19px;
				line-height: 1.6;
				max-width: 620px;
				color: #f0ece4;
				margin-bottom: 30px;
			}
		}

		.services-nav {
			gap: 0 !important;
			margin: 0;
			padding: 0;
		}

		.services-nav .nav-link,
		.services-nav .nav-link.active {
			background: transparent;
			box-shadow: none;
			line-height: 1.3;
		}
	}
}

@media (prefers-reduced-motion: reduce) {
	body.is-frontend #main :is(.dx-service-scene-layer, .dx-pulse-scene) {
		transition: none;
		transform: none;
	}
}

// Keep the top of the cinematic hero continuous behind the unscrolled header.
body.post-type-archive-dx_bus_poll #header:not(.scrolled):not(:has(.navbar-collapse.show, .navbar-collapse.collapsing)) {
	background: transparent !important;
	backdrop-filter: none;
	box-shadow: none;
}

// Instagram content must remain readable while the third-party embed loads/resizes.
body.is-frontend #main .dx-instagram,
body.is-frontend #main .dx-instagram .dx-instagram__intro,
body.is-frontend #main .dx-instagram .dx-instagram__intro > *,
body.is-frontend #main .dx-instagram .dx-instagram__feed {
	opacity: 1 !important;
	visibility: visible !important;
}
