/* Shared editorial presentation, October 2026. */
body.is-frontend {
	#header {
		&:after {
			display: none !important;
		}
		& {
			background: transparent !important;
			backdrop-filter: none !important;
		}
	}
	&:not(.nav-open) #header .dxndre-nav-left,
	&:not(.nav-open) #header .dxndre-nav-right,
	&:not(.nav-open) #header .navbar-brand {
		color: white !important;
	}
}
body.is-frontend.nav-open {
	overflow: hidden !important;
	overscroll-behavior: none;
}
body.is-frontend {
	#navbar.dx-menu {
		background: rgba(4, 5, 5, 0.94);
		backdrop-filter: blur(24px);
		overscroll-behavior: contain;
	}
	#header {
		#navbar {
			.dx-menu__list {
				& > li > a {
					align-items: baseline !important;
					--link-tone: #d7ad57;
					transition:
						color 0.4s ease,
						padding 0.4s ease;
				}
				& > li > a:after {
					background: linear-gradient(currentColor, currentColor) left
						calc(100% - 2px) / calc(100% - 33px) 1px no-repeat;
					color: rgba(255, 255, 255, 0.25);
					align-self: baseline;
					transition: color 0.45s ease !important;
				}
				& > li > a:is(:hover, :focus-visible):after {
					color: var(--link-tone);
				}
				& > li > a:is(:hover, :focus-visible):before {
					background: var(--link-tone);
				}
				& > li > a[href*="/buses"] {
					--link-tone: #f14646;
				}
				& > li > a[href*="/fitness"]:is(:hover, :focus-visible) {
					color: #d7ad57;
				}
			}
		}
	}
}
.dx-home-icon {
	width: 34px;
	height: 34px;
	display: inline-block;
	vertical-align: bottom;
}
img {
	-webkit-user-drag: none;
	user-select: none;
}
a,
button,
[role="button"],
.btn {
	transition:
		color 0.35s ease,
		background-color 0.35s ease,
		border-color 0.35s ease,
		opacity 0.35s ease,
		transform 0.35s ease,
		outline-color var(--dx-focus-duration, 0s) ease;
}
body.is-frontend.home #main .cover-content h2 {
	font-size: clamp(48px, 4.8vw, 116px) !important;
}
@keyframes dx-hue {
	to {
		filter: hue-rotate(360deg);
	}
}
