/* Masonry columns preserve each photo's proportions without row-sized gaps. */
.dxb {
	& #dxb-gallery.dxb-gallery {
		display: block !important;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card {
		position: relative;
		display: block !important;
		break-inside: avoid;
		margin: 0 0 14px;
		padding: 0;
		width: 100%;
		transform: none;
		border: 0;
		overflow: hidden;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card[hidden] {
		display: none !important;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card img {
		display: block;
		width: 100%;
		height: auto !important;
		aspect-ratio: auto !important;
		margin: 0;
		transition:
			filter 0.5s ease,
			transform 0.65s ease;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card > div {
		position: absolute;
		inset: 0;
		display: flex;
		flex-direction: column;
		justify-content: flex-end;
		align-items: flex-start;
		background: linear-gradient(0deg, #000d, #0003);
		opacity: 0;
		transition: opacity 0.4s ease;
		color: white;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card > div:after {
		content: "PRESS TO ENLARGE ↗\FE0E";
		position: absolute;
		right: 16px;
		top: 18px;
		writing-mode: vertical-rl;
		letter-spacing: 0.16em;
		font-size: 9px;
		color: white;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card > div > span:last-child {
		display: none;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card:is(:hover, :focus-visible) > div {
		opacity: 1;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card:is(:hover, :focus-visible) img {
		filter: blur(4px) brightness(0.65);
		transform: scale(1.035);
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card h3 {
		line-height: 1.2;
		color: white;
		margin: 6px 0 0;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card.dx-photo-pending {
		opacity: 0;
		translate: 0 35px;
	}
}
.dxb {
	& #dxb-gallery .dxb-photo-card {
		transition:
			opacity 0.7s ease,
			translate 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
	}
}
#dxb-photo-map {
	& iframe {
		filter: invert(0.92) hue-rotate(180deg) saturate(0.45);
		color-scheme: dark;
	}
}
/* Portfolio hero and scroll-driven project reel. */
.dx-portfolio-hero {
	position: relative;
	isolation: isolate;
	height: 100svh;
	background: #090909;
	padding: 160px 5vw 60px;
	color: #eee;
	overflow: hidden;
	& h1 {
		line-height: 1;
		letter-spacing: -0.065em;
		font-weight: 400;
		white-space: nowrap;
		margin: 0;
		position: relative;
		z-index: 0;
	}
	&:before {
		content: "";
		position: absolute;
		right: -5%;
		bottom: -15%;
		width: 65%;
		height: 90%;
		background: radial-gradient(ellipse, #7b695b80, transparent 65%);
		z-index: -1;
