/* ==========================================================================
   Account Sky
   ========================================================================== */

// Decoration is contained inside the existing account background, behind its controls.
body.is-frontend :is(.auth.dx-account-photo, .dx-404-hero) .dx-account-sky {
	position: absolute;
	inset: 0;
	z-index: 0;
	overflow: hidden;
	contain: layout paint;
	pointer-events: none;
	user-select: none;

	span {
		display: block;
		position: absolute;
		pointer-events: none;
	}

	.dx-account-sky__daytime,
	.dx-account-sky__nighttime {
		inset: 0;
		opacity: 0;
		transition: opacity 1.4s ease;
	}

	.dx-account-sky__sun-glare {
		left: 74%;
		top: 34%;
		width: clamp(240px, 31vw, 480px);
		aspect-ratio: 1;
		translate: -50% -50%;
		background: radial-gradient(
			circle,
			#fff9dcaa 0,
			#fff2ad30 9%,
			transparent 25%,
			#fffbe817 31%,
			transparent 43%
		);
		mix-blend-mode: screen;
		animation: dx-account-sun-glare 14s ease-in-out infinite alternate;
	}

	.dx-account-sky__flare {
		aspect-ratio: 1;
		border: 1px solid #d5d7fa40;
		border-radius: 50%;
		background: radial-gradient(
			circle,
			#a3c0ff05 35%,
			#dbe5ff28 70%,
			transparent 73%
		);
		mix-blend-mode: screen;
		animation: dx-account-sun-glare 18s ease-in-out -6s infinite alternate;
	}

	.dx-account-sky__flare--one {
		left: 57%;
		top: 46%;
		width: 42px;
	}

	.dx-account-sky__flare--two {
		left: 48%;
		top: 56%;
		width: 17px;
		opacity: 0.4;
		animation-delay: -12s;
	}

	.dx-account-sky__bird-flight {
		left: -40px;
		top: var(--flight-top);
		width: var(--bird-width);
		height: 14px;
		color: #101a2e;
		animation: dx-account-bird-flight var(--flight-duration) linear
			var(--flight-delay) infinite;
	}

	.dx-account-sky__bird {
		display: block;
		width: 100%;
		height: 100%;
		fill: currentColor;
		transform-origin: center 70%;
		animation: dx-account-bird-wing 1.2s ease-in-out infinite alternate;
	}

	.dx-account-sky__plane-flight {
		left: -50px;
		top: 31%;
		width: 26px;
		height: 26px;
		color: #f3f0e8;
		opacity: 0;
		animation: dx-account-plane-flight 76s linear -13s infinite;

		&::before {
			content: "";
			position: absolute;
			top: 12px;
			right: 23px;
			width: 55px;
			height: 1px;
			background: linear-gradient(90deg, transparent, #edf4f54d);
		}
	}

	.dx-account-sky__plane {
		display: block;
		width: 100%;
		height: 100%;
		fill: currentColor;
		transform: rotate(90deg);
	}

	.dx-account-sky__moon {
		left: 83%;
		top: 21%;
		width: clamp(34px, 4vw, 56px);
		aspect-ratio: 1;
		color: #fff6db;
		opacity: 0;
		filter: drop-shadow(0 0 12px #c9ddff4d);
		transition: opacity 1.4s ease;
		animation: dx-account-moon-drift 24s ease-in-out infinite alternate;
	}

	.dx-account-sky__moon-disc {
		display: block;
		width: 100%;
		height: 100%;
		fill: currentColor;
	}

	.dx-account-sky__star {
		width: var(--star-size);
		height: var(--star-size);
		max-width: 4px;
		max-height: 4px;
		border-radius: 50%;
		background: #edf3ff;
		box-shadow: 0 0 4px #d9e6ff66;
		opacity: 0.55;

		&.is-twinkling {
			animation: dx-account-star-twinkle var(--twinkle-duration)
				ease-in-out var(--twinkle-delay) infinite alternate;
		}
	}

	.dx-account-sky__shooting-star {
		width: 90px;
		height: 1px;
		background: linear-gradient(90deg, #f6f8ff, transparent);
		opacity: 0;
		transform-origin: left center;
		animation: dx-account-shooting-star 29s linear -8s infinite;

		&::before {
			content: "";
			position: absolute;
			left: 0;
			top: -1px;
			width: 3px;
			height: 3px;
			border-radius: 50%;
			background: #fff;
			box-shadow: 0 0 5px #fff9;
		}
	}

	.dx-account-sky__shooting-star--one {
		left: 78%;
		top: 15%;
	}

	.dx-account-sky__shooting-star--two {
		left: 93%;
		top: 47%;
		animation-duration: 43s;
		animation-delay: -22s;
	}

	&:is(
			[data-sky-period="day"],
			[data-sky-period="dawn"],
			[data-sky-period="dusk"]
		)
		.dx-account-sky__daytime {
		opacity: 1;
	}

	&:is([data-sky-period="dawn"], [data-sky-period="dusk"])
		.dx-account-sky__sun-glare {
		top: 60%;
		background: radial-gradient(
			circle,
			#ffe4b160 0,
			#ffc87c24 12%,
			transparent 28%,
			#ffcf9e0f 35%,
			transparent 45%
		);
	}

	&[data-sky-period="dusk"] .dx-account-sky__moon {
		opacity: 0.7;
	}

	&[data-sky-period="night"] {
		.dx-account-sky__nighttime,
		.dx-account-sky__moon {
			opacity: 0.9;
		}
		.dx-account-sky__daytime * {
			animation-play-state: paused;
		}
	}

	&:not([data-sky-period="night"]) .dx-account-sky__nighttime *,
	&:is([data-sky-period="day"], [data-sky-period="dawn"])
		.dx-account-sky__moon {
		animation-play-state: paused;
	}

	&[data-sky-paused="true"] * {
		animation-play-state: paused !important;
	}
}

@keyframes dx-account-sun-glare {
	from {
		opacity: 0.35;
		transform: scale(0.96);
	}
	to {
		opacity: 0.65;
		transform: scale(1.05);
	}
}
@keyframes dx-account-bird-flight {
	0% {
		opacity: 0;
		transform: translate3d(0, 0, 0);
	}
	5% {
		opacity: 0.5;
	}
	62% {
		opacity: 0.5;
	}
	68%,
	100% {
		opacity: 0;
		transform: translate3d(calc(100vw + 100px), -35px, 0);
	}
}
@keyframes dx-account-bird-wing {
	from {
		transform: scaleY(0.72);
	}
	to {
		transform: scaleY(1);
	}
}
@keyframes dx-account-plane-flight {
	0% {
		opacity: 0;
		transform: translate3d(0, 0, 0) rotate(-12deg);
	}
	4% {
		opacity: 0.5;
	}
	35% {
		opacity: 0.5;
	}
	40%,
	100% {
		opacity: 0;
		transform: translate3d(calc(100vw + 140px), -13vh, 0) rotate(-12deg);
	}
}
@keyframes dx-account-moon-drift {
	from {
		transform: translate3d(0, 0, 0) rotate(-5deg);
	}
	to {
		transform: translate3d(0, -4px, 0) rotate(3deg);
	}
}
@keyframes dx-account-star-twinkle {
	0%,
	15% {
		opacity: 0.2;
		transform: scale(0.7);
	}
	70%,
	100% {
		opacity: 0.9;
		transform: scale(1);
	}
}
@keyframes dx-account-shooting-star {
	0%,
	2% {
		opacity: 0;
		transform: translate3d(0, 0, 0) rotate(-33deg) scaleX(0.2);
	}
	3% {
		opacity: 0.9;
		transform: translate3d(-40px, 26px, 0) rotate(-33deg) scaleX(1);
	}
	7%,
	100% {
		opacity: 0;
		transform: translate3d(-280px, 182px, 0) rotate(-33deg) scaleX(0.4);
	}
}

@media (prefers-reduced-motion: reduce) {
	body.is-frontend :is(.auth.dx-account-photo, .dx-404-hero) .dx-account-sky {
		*,
		*::before {
			animation: none !important;
