// October26 evening — viewport waterfront, calculator handoff and optical word reveal.
body.proposal.has-proposal-waterfront {
	#wrapper {
		position: relative;
		z-index: 1;
	}
	#main {
		background: transparent !important;
	}
}
.dx-proposal-waterfront {
	position: fixed;
	inset: -36px 0;
	z-index: 0;
	pointer-events: none;
	background:
		linear-gradient(90deg, rgba(6, 12, 9, 0.88), rgba(6, 12, 9, 0.46)),
		url("./img/proposal-skyline-illustrated.webp") center / cover no-repeat;
	opacity: 0;
	transform: translate3d(0, var(--waterfront-drift, 0px), 0);
	transition: opacity 0.95s ease;
	&.is-visible {
		opacity: 1;
	}
}
body.is-frontend {
	#main {
		.enquiry-calculator-note {
			margin: -10px 0 32px;
			padding: 18px 22px;
			border-left: 2px solid #d7ad57;
			background: rgba(215, 173, 87, 0.08);
			color: #eee9dd;
			font-size: clamp(14px, 1.15vw, 17px);
			line-height: 1.65;
		}
		.dx-photo-hero h1 {
			font-size: clamp(46px, 7.5vw, 144px) !important;
			max-width: 16ch;
			line-height: 1.04;
		}
		.dx-lens-word {
			display: inline-block;
			color: #d7ad57;
			transform-origin: center;
			animation: dx-lens-word-focus 1.65s cubic-bezier(0.22, 1, 0.36, 1)
				0.25s both;
		}
	}
}
@keyframes dx-lens-word-focus {
	0% {
		opacity: 0;
		filter: blur(14px);
		transform: scale(1.14);
		clip-path: inset(0 49%);
	}
	45% {
		opacity: 1;
		filter: blur(3px);
		clip-path: inset(0 0);
	}
	100% {
		opacity: 1;
		filter: blur(0);
		transform: scale(1);
		clip-path: inset(0 0);
	}
}
